window.AP_PSYCHOLOGY_DECKS = [{"id":"appsych-unit-0","name":"AP Psychology - Unit 0","shortName":"Unit 0: Science Practices and Research Methods","builtIn":true,"sourceTitle":"Myer's Psychology for AP Vocabulary","sourceUrl":"https://www.bpsgroverteacher.com/uploads/1/4/8/4/14847764/myer_s_psychology_for_ap_vocab.pdf","cedTitle":"AP Psychology Course and Exam Description - Effective Fall 2025","cedUrl":"https://apcentral.collegeboard.org/media/pdf/ap-psychology-course-and-exam-description.pdf","cards":[{"id":"appsych-unit-0-c1","front":"applied research","back":"Scientific study that aims to solve practical problems.","sourceNumber":29},{"id":"appsych-unit-0-c2","front":"basic research","back":"Pure science that aims to increase the scientific knowledge base. 6.","sourceNumber":48},{"id":"appsych-unit-0-c3","front":"behaviorism","back":"The view that psychology (1) should be an  objective science that (2) studies behavior without reference to mental processes. Most research psychologists today agree with (1) but not with (2). 7.","sourceNumber":54},{"id":"appsych-unit-0-c4","front":"case study","back":"An observation technique in which one person is studied in depth in the hope of revealing universal principles.","sourceNumber":72},{"id":"appsych-unit-0-c5","front":"Confidentiality","back":"The ethical duty to protect participants' private information and limit access to identifiable research data.","sourceNumber":"supplement-9"},{"id":"appsych-unit-0-c6","front":"confounding variable","back":"A factor other than the independent variable that might produce an effect in an experiment.","sourceNumber":110},{"id":"appsych-unit-0-c7","front":"content validity","back":"The extent to which a test samples the behavior that is of interest.","sourceNumber":114},{"id":"appsych-unit-0-c8","front":"control group","back":"In an experiment, the group that is not exposed to the treatment; contrasts with the experimental group and serves as a comparison for evaluating the effect of the treatment.","sourceNumber":116},{"id":"appsych-unit-0-c9","front":"correlation","back":"A measure of the extent to which two factors vary  together, and thus of how well either factor predicts the other.","sourceNumber":120},{"id":"appsych-unit-0-c10","front":"correlation coefficient","back":"A statistical index of the relationship between two things (from -1 to +1). 1.","sourceNumber":121},{"id":"appsych-unit-0-c11","front":"cross-sectional study","back":"A study in which people of different  ages are compared with one another.","sourceNumber":127},{"id":"appsych-unit-0-c12","front":"debriefing","back":"The postexperimental explanation for a study, including its purpose and any deceptions, to its participants.","sourceNumber":132},{"id":"appsych-unit-0-c13","front":"Deception in research","back":"Withholding or misrepresenting information only when scientifically justified, risk is minimized, alternatives are unavailable, and participants are debriefed afterward.","sourceNumber":"supplement-12"},{"id":"appsych-unit-0-c14","front":"dependent variable","back":"The outcome factor; the variable that may change in response to manipulations of the independent variable.","sourceNumber":140},{"id":"appsych-unit-0-c15","front":"Descriptive statistics","back":"Numerical methods that organize and summarize a data set, including measures of central tendency, variability, and distributions.","sourceNumber":"supplement-1"},{"id":"appsych-unit-0-c16","front":"double-blind procedure","back":"An experiment procedure in which both the research participants and the research staff are ignorant (blind) about whether the research participants have received the treatment or a placebo. Commonly used in drug-evaluation studies. 1.","sourceNumber":155},{"id":"appsych-unit-0-c17","front":"empiricism","back":"The view that knowledge originates in experience and that science should, therefore, rely and observation and experimentation.","sourceNumber":175},{"id":"appsych-unit-0-c18","front":"evidence based practice","back":"Clinical decision-making that integrates the best available research with clinical expertise and patient characteristics and preferences.","sourceNumber":182},{"id":"appsych-unit-0-c19","front":"experiment","back":"A research method in which an investigator manipulates one or more factors (independent variables) to observe the effect on some behavior or mental process (the dependent variable). By random assignment of participants, the experimenter aims to control other relevant factors.","sourceNumber":185},{"id":"appsych-unit-0-c20","front":"experimental group","back":"In an experiment, the group that is exposed to the treatment, that is, to one version of the independent variable.","sourceNumber":186},{"id":"appsych-unit-0-c21","front":"experimental psychology","back":"The study of behavior and thinking using the experimental method.","sourceNumber":187},{"id":"appsych-unit-0-c22","front":"factor analysis","back":"A statistical procedure that identifies clusters of related items (called factors) on a test; used to identify different  dimensions of performance that underlie a person's total score.","sourceNumber":195},{"id":"appsych-unit-0-c23","front":"Generalizability","back":"The extent to which findings from a sample and research setting can reasonably apply to other people, populations, or situations.","sourceNumber":"supplement-7"},{"id":"appsych-unit-0-c24","front":"hindsight bias","back":"The tendency to believe, after learning an outcome, that one would have foreseen it. (Also known as the I- knew-it-all-along phenomenon.).","sourceNumber":249},{"id":"appsych-unit-0-c25","front":"hypothesis","back":"A testable prediction, often implied by a theory.","sourceNumber":259},{"id":"appsych-unit-0-c26","front":"illusory correlation","back":"The perception of a relationship where none exists.","sourceNumber":265},{"id":"appsych-unit-0-c27","front":"independent variable","back":"The experimental factor that is manipulated; the variable whose effect is being studied.","sourceNumber":271},{"id":"appsych-unit-0-c28","front":"Inferential statistics","back":"Methods that use sample data to draw conclusions about a larger population and estimate whether an observed result is likely due to chance.","sourceNumber":"supplement-2"},{"id":"appsych-unit-0-c29","front":"informed consent","back":"An ethical principle that research  participants be told enough to enable them to choose whether they wish to participate. 2.","sourceNumber":275},{"id":"appsych-unit-0-c30","front":"Institutional review board","back":"A committee that evaluates proposed research involving human participants to protect their rights, safety, and welfare.","sourceNumber":"supplement-8"},{"id":"appsych-unit-0-c31","front":"longitudinal study","back":"Research in which the same people are  restudied and retested over a long period.","sourceNumber":314},{"id":"appsych-unit-0-c32","front":"mean","back":"The arithmetic average of a distribution, obtained by adding the scores and then dividing by the number of scores. 3.","sourceNumber":321},{"id":"appsych-unit-0-c33","front":"median","back":"The middle score in a distribution; half the scores are above it and half are below it. 3.","sourceNumber":322},{"id":"appsych-unit-0-c34","front":"meta-analysis","back":"A procedure for statistically combining the results of many different research studies.","sourceNumber":332},{"id":"appsych-unit-0-c35","front":"mode","back":"The most frequently occurring score(s) in a distribution.","sourceNumber":339},{"id":"appsych-unit-0-c36","front":"naturalistic observation","back":"Observing and recording behavior in naturally occurring situations without trying to manipulate and control the situation.","sourceNumber":355},{"id":"appsych-unit-0-c37","front":"Negative correlation","back":"A relationship in which one variable tends to increase as the other decreases; it does not by itself establish causation.","sourceNumber":"supplement-4"},{"id":"appsych-unit-0-c38","front":"normal curve","back":"A symmetrical, bell-shaped curve that describes the distribution of many types of data; most scores fall near the mean (68% fall within one standard deviation of it) and fewer and fewer near the extremes.","sourceNumber":367},{"id":"appsych-unit-0-c39","front":"operational definition","back":"A statement of the procedures (operations) used to define research variables. For example, human intelligence may be operationally defined as what an intelligence test measures.","sourceNumber":379},{"id":"appsych-unit-0-c40","front":"Percentile rank","back":"The percentage of scores in a distribution that are at or below a particular score.","sourceNumber":"supplement-6"},{"id":"appsych-unit-0-c41","front":"placebo effect","back":"Experimental results caused by expectations alone; any effect on behavior caused by the administration of an inert substance or condition, which the recipient assumes is an active agent.","sourceNumber":414},{"id":"appsych-unit-0-c42","front":"population","back":"All the cases in a group being studied, from which samples may be drawn. (Note: Except for national studies, this  does not refer to a country's whole population.).","sourceNumber":417},{"id":"appsych-unit-0-c43","front":"Positive correlation","back":"A relationship in which two variables tend to increase together or decrease together; it does not by itself establish causation.","sourceNumber":"supplement-3"},{"id":"appsych-unit-0-c44","front":"predictive validity","back":"The success with which a test predicts the behavior it is designed to predict; it is assessed by computing the correlation between test scores and the criterion behavior. (Also called criterion-related validity).","sourceNumber":423},{"id":"appsych-unit-0-c45","front":"Protection from harm","back":"The ethical requirement that researchers minimize physical and psychological risk and stop a study when participant welfare is threatened.","sourceNumber":"supplement-10"},{"id":"appsych-unit-0-c46","front":"random assignment","back":"Assigning participants to experimental and control groups by chance, thus minimizing preexisting differences between those assigned to the different groups.","sourceNumber":455},{"id":"appsych-unit-0-c47","front":"random sample","back":"A sample that fairly represents a population because each member has an equal chance of inclusion.","sourceNumber":456},{"id":"appsych-unit-0-c48","front":"range","back":"The difference between the highest and lower scores in a distribution. 4.","sourceNumber":457},{"id":"appsych-unit-0-c49","front":"regression toward the mean","back":"The tendency for extreme or unusual scores to regress toward their average 4.","sourceNumber":467},{"id":"appsych-unit-0-c50","front":"replication","back":"Repeating the essence of a research study, usually with different participants in different situations, to see whether the basic finding extends to other participants and circumstances.","sourceNumber":476},{"id":"appsych-unit-0-c51","front":"Right to withdraw","back":"The ethical principle that participants may leave a study at any time without penalty.","sourceNumber":"supplement-11"},{"id":"appsych-unit-0-c52","front":"scatterplot","back":"A graphed cluster of dots, each of which represents the values of two variables. The slope of the points suggests the  direction of the relationship between the two variables. The amount of scatter suggests the strength of the correlation (little scatter indicates high correlation).","sourceNumber":495},{"id":"appsych-unit-0-c53","front":"Skewed distribution","back":"A distribution in which scores extend farther on one side than the other, often pulling the mean toward the long tail.","sourceNumber":"supplement-5"},{"id":"appsych-unit-0-c54","front":"standard deviation","back":"A computed measure of how much scores vary around the mean score.","sourceNumber":547},{"id":"appsych-unit-0-c55","front":"statistical significance","back":"A statistical statement of how likely it is that an obtained result occurred by chance. 5.","sourceNumber":550},{"id":"appsych-unit-0-c56","front":"survey","back":"A technique for ascertaining the self-reported attitudes or behaviors of a particular group, usually by questioning a representative, random sample of the group.","sourceNumber":562},{"id":"appsych-unit-0-c57","front":"theory","back":"An explanation using an integrated set of principles that organizes observations and predicts behaviors or events.","sourceNumber":578},{"id":"appsych-unit-0-c58","front":"validity","back":"The extent to which a test measures or predicts what it is supposed to.","sourceNumber":596}],"questions":[],"feynmanPrompts":[{"id":"appsych-unit-0-f1","prompt":"Experimental design"},{"id":"appsych-unit-0-f2","prompt":"Correlation and causation"},{"id":"appsych-unit-0-f3","prompt":"Sampling and generalizability"},{"id":"appsych-unit-0-f4","prompt":"Descriptive and inferential statistics"},{"id":"appsych-unit-0-f5","prompt":"Ethics in psychological research"}]},{"id":"appsych-unit-1","name":"AP Psychology - Unit 1","shortName":"Unit 1: Biological Bases of Behavior","builtIn":true,"sourceTitle":"Myer's Psychology for AP Vocabulary","sourceUrl":"https://www.bpsgroverteacher.com/uploads/1/4/8/4/14847764/myer_s_psychology_for_ap_vocab.pdf","cedTitle":"AP Psychology Course and Exam Description - Effective Fall 2025","cedUrl":"https://apcentral.collegeboard.org/media/pdf/ap-psychology-course-and-exam-description.pdf","cards":[{"id":"appsych-unit-1-c1","front":"absolute threshold","back":"The minimum stimulation needed to detect a particular stimulus 50 percent of the time.","sourceNumber":2},{"id":"appsych-unit-1-c2","front":"Accommodation (vision)","back":"Act or state of adjustment or adaptation, changes in shape of the occular lens for various focal distances.","sourceNumber":5},{"id":"appsych-unit-1-c3","front":"action potential","back":"A neural impulse; a brief electrical charge that travels down an axon.","sourceNumber":8},{"id":"appsych-unit-1-c4","front":"adrenal glands","back":"A pair of endocrine glands that sit just above the kidneys and secrete hormones (epinephrine and norepinephrine) that help arouse the body in times of stress.","sourceNumber":13},{"id":"appsych-unit-1-c5","front":"Alpha waves","back":"The relatively slow brain waves of a relaxed,  awake state.","sourceNumber":17},{"id":"appsych-unit-1-c6","front":"amphetamines","back":"Drugs that stimulate neural activity, causing speeded-up body functions and associated energy and mood changes 3.","sourceNumber":20},{"id":"appsych-unit-1-c7","front":"amygdala","back":"Two lima bean-sized neural clusters in the limbic system; linked to emotion.","sourceNumber":21},{"id":"appsych-unit-1-c8","front":"autonomic nervous system","back":"The part of the peripheral nervous system that controls the glands and the muscles of the internal organs (such as the heart). Its sympathetic division  arouses; its parasympathetic division calms.","sourceNumber":41},{"id":"appsych-unit-1-c9","front":"axon","back":"The extension of a neuron, ending in branching terminal fibers through which messages pass to other neurons or to  muscles or glands.","sourceNumber":44},{"id":"appsych-unit-1-c10","front":"barbiturates","back":"Drugs that depress the activity of the central  nervous system, reducing anxiety but impairing memory and judgement.","sourceNumber":46},{"id":"appsych-unit-1-c11","front":"behavior genetics","back":"The study of the relative power and limits of genetic and environmental influences on behavior.","sourceNumber":50},{"id":"appsych-unit-1-c12","front":"biological psychology","back":"A branch of psychology that studies the links between biological (including neuroscience and behavior genetics) and psychological processes.","sourceNumber":60},{"id":"appsych-unit-1-c13","front":"blind spot","back":"The point at which the optic nerve leaves the eye, creating a blind spot because no receptor cells are located there.","sourceNumber":65},{"id":"appsych-unit-1-c14","front":"brainstem","back":"The oldest part and central core of the brain, beginning where the spinal cord swells as it enters the skull; is responsible for automatic survival functions.","sourceNumber":67},{"id":"appsych-unit-1-c15","front":"cerebellum","back":"The \"little brain\" at the rear of the brainstem; functions include processing sensory input and coordinating movement output and balance.","sourceNumber":76},{"id":"appsych-unit-1-c16","front":"chromosomes","back":"Threadlike structures made of DNA molecules that contain the genes.","sourceNumber":79},{"id":"appsych-unit-1-c17","front":"Circadian rhythm","back":"The biological clock; regular bodily rhythms (for example, of temperature and wakefulness) that occur on a 24-hour cycle.","sourceNumber":81},{"id":"appsych-unit-1-c18","front":"Cochlea","back":"The fluid-filled, coiled tunnel in the inner ear that contains the receptors for hearing.","sourceNumber":85},{"id":"appsych-unit-1-c19","front":"cochlear implant","back":"A device for converting sounds into electrical signals and stimulating the auditory nerve through electrodes threaded into the cochlea.","sourceNumber":86},{"id":"appsych-unit-1-c20","front":"conduction hearing loss","back":"Hearing loss caused by damage to the mechanical system that conducts sound waves to the cochlea.","sourceNumber":105},{"id":"appsych-unit-1-c21","front":"cones","back":"Retinal receptor cells that are concentrated near the center of the retina and that function in daylight or in well-lit conditions. The cones detect fine detail and give rise to color sensations.","sourceNumber":106},{"id":"appsych-unit-1-c22","front":"corpus callosum","back":"The large band of neural fibers connecting  the two brain hemispheres and carrying messages between them.","sourceNumber":119},{"id":"appsych-unit-1-c23","front":"CT (computed tomography) scan","back":"A series of X-ray photographs taken from different angles and combined by computer into a composite representation of a slice through the body. Also called CAT scan. 1.","sourceNumber":129},{"id":"appsych-unit-1-c24","front":"delta waves","back":"The large, slow brain waves associated with deep sleep.","sourceNumber":136},{"id":"appsych-unit-1-c25","front":"dendrite","back":"The bushy, branching extensions of a neuron that receive messages and conduct impulses toward the cell body.","sourceNumber":138},{"id":"appsych-unit-1-c26","front":"depressants","back":"Drugs (such as alcohol, barbiturates, and opiates) that reduce neural activity and slow body functions.","sourceNumber":141},{"id":"appsych-unit-1-c27","front":"difference threshold","back":"The minimum difference between two stimuli required for detection 50 percent of the time. We experience the difference threshold as a just noticeable difference. (Also called just noticeable difference or JND.).","sourceNumber":145},{"id":"appsych-unit-1-c28","front":"DNA (deoxyribonucleic acid)","back":"A complex molecule containing the genetic information that makes up the chromosomes.","sourceNumber":153},{"id":"appsych-unit-1-c29","front":"dream","back":"A sequence of images, emotions, and thoughts passing through a sleeping person's mind. ______ are notable for their  hallucinatory imagery, discontinuities, and incongruities, and for the dreamer's delusional acceptance of the content and later difficulties remembering it. 1.","sourceNumber":157},{"id":"appsych-unit-1-c30","front":"Ecstacy (MDMA)","back":"A synthetic stimulant and mild hallucinogen. Produces euphoria and social intimacy, but with short-term health risks and longer-term harm to serotonin- producing neurons and to mood and cognition.","sourceNumber":163},{"id":"appsych-unit-1-c31","front":"electroencephalogram","back":"An amplified recording of the waves of electrical activity that sweep across the brain's surface. These waves are measured by electrodes placed on the scalp.","sourceNumber":169},{"id":"appsych-unit-1-c32","front":"endocrine system","back":"The body's \"slow\" chemical communication system; a set of glands that secrete hormones into the blood stream.","sourceNumber":177},{"id":"appsych-unit-1-c33","front":"endorphins","back":"\"morphine within\" - natural, opiatelike neurotransmitters linked to pain control and to pleasure.","sourceNumber":178},{"id":"appsych-unit-1-c34","front":"environment","back":"Every nongenetic influence, from prenatal nutrition to the people and things around us.","sourceNumber":179},{"id":"appsych-unit-1-c35","front":"estrogens","back":"Sex hormones, such as estradiol, secreted in greater amounts by females than by males and contributing to female sex characteritics; in nonhuman female mammals, estrogen levels peak during ovulation, promoting sexual receptivity.","sourceNumber":181},{"id":"appsych-unit-1-c36","front":"extrasensory perception","back":"The controversial claim that perception can occur apart from sensory input. Said to include  telepathy, clairvoyance, and precognition.","sourceNumber":192},{"id":"appsych-unit-1-c37","front":"feature detectors","back":"Nerve cells in the brain that respond to  specific features of the stimulus, such as shape, angle, or movement.","sourceNumber":197},{"id":"appsych-unit-1-c38","front":"fMRI (functional MRI)","back":"A technique for revealing bloodflow and, therefore, brain activity by comparing successive MRI scans. Shows brain function.","sourceNumber":208},{"id":"appsych-unit-1-c39","front":"fovea","back":"The central focal point in the retina, around which the eye's cones cluster.","sourceNumber":211},{"id":"appsych-unit-1-c40","front":"fraternal twins","back":"Twins who develop from separate fertilized eggs. They are genetically no closer that brothers and sisters, but they share a fetal environment.","sourceNumber":213},{"id":"appsych-unit-1-c41","front":"frequency theory","back":"In hearing, the theory that the rate of nerve impulses traveling up the auditory nerve matches the frequency of a tone, thus enabling us to sense its pitch.","sourceNumber":216},{"id":"appsych-unit-1-c42","front":"frontal lobes","back":"Portion of the cerebral cortex lying just behind the forehead; involved in speaking and muscle movements and in making plans and judgements.","sourceNumber":217},{"id":"appsych-unit-1-c43","front":"gate-control theory","back":"Theory that spinal cord contains neurological gate that blocks pains signals or allows them to pass. gate is opened by activity of pain going up small nerve fibers & gate is closed by act of large fibers or by info coming from brain.","sourceNumber":222},{"id":"appsych-unit-1-c44","front":"genes","back":"The biochemical units of heredity that make up the chromosomes; segments of DNA capable of synthesizing a protein.","sourceNumber":231},{"id":"appsych-unit-1-c45","front":"genome","back":"The complete instructions for making an organism, consisting of all the genetic material in that organism's chromosomes.","sourceNumber":232},{"id":"appsych-unit-1-c46","front":"glial cell","back":"Cells in the nervous system that support, nourish, and protect neurons.","sourceNumber":234},{"id":"appsych-unit-1-c47","front":"hallucinogens","back":"Psychedelic (\"mind-manifesting\") drugs, such  as LSD, that distort perceptions and evoke sensory images in the absence of sensory input.","sourceNumber":243},{"id":"appsych-unit-1-c48","front":"hippocampus","back":"A neural center that is located in the limbic system; helps process explicit memories for storage.","sourceNumber":250},{"id":"appsych-unit-1-c49","front":"hormones","back":"Chemical messengers that are manufactured buy the endocrine glands, travel through the bloodstream, and affect other tissues.","sourceNumber":252},{"id":"appsych-unit-1-c50","front":"hypothalamus","back":"A neural structure lying below the thalamus; it directs several maintenance activities (eating, drinking, body temperature), helps govern the endocrine system via the pituitary gland, and is linked to emotion and reward.","sourceNumber":258},{"id":"appsych-unit-1-c51","front":"identical twins","back":"Twins who develop from a single fertilized egg that splits in two, creating two genetically identical organisms.","sourceNumber":262},{"id":"appsych-unit-1-c52","front":"inner ear","back":"Structures and liquids that relay sound waves to the auditory nerve fibers on a path to the brain for interpretation of sound 2.","sourceNumber":278},{"id":"appsych-unit-1-c53","front":"insomnia","back":"Recurring problems in falling or staying asleep.","sourceNumber":282},{"id":"appsych-unit-1-c54","front":"interneurons","back":"Neurons within the brain and spinal cord that communicate internally and intervene between sensory inputs and motor outputs.","sourceNumber":291},{"id":"appsych-unit-1-c55","front":"lens","back":"The transparent structure behind the pupil that changes shape to help focus images on the retina.","sourceNumber":306},{"id":"appsych-unit-1-c56","front":"lesion","back":"Tissue destruction; a brain lesion is a naturally or experimentally caused destruction of brain tissue. 3.","sourceNumber":307},{"id":"appsych-unit-1-c57","front":"limbic system","back":"Doughnut-shaped neural system (including the hippocampus, amygdala, and hypothalamus) located below the  cerebral hemispheres; associated with emotions and drives.","sourceNumber":309},{"id":"appsych-unit-1-c58","front":"lobotomy","back":"Invented by Egas Moniz, a now-rare psychosurgical procedure once used to calm uncontrollably emotional or violent patients. The procedure cut the nerves connecting the frontal  loves to the emotion-controlling centers of the inner brain.","sourceNumber":311},{"id":"appsych-unit-1-c59","front":"LSD","back":"A powerful hallucinogenic drug; also known as acid (lysergic acid diethylamide).","sourceNumber":315},{"id":"appsych-unit-1-c60","front":"medulla","back":"The base of the brainstem; controls heartbeat and  breathing.","sourceNumber":324},{"id":"appsych-unit-1-c61","front":"methamphetamine","back":"A powerfully addictive drug that stimulates the central nervous system, with speeded-up body functions and associated energy and mood changes; over time, appears to reduce baseline dopamine levels.","sourceNumber":333},{"id":"appsych-unit-1-c62","front":"mirror neurons","back":"Frontal lobe neurons that fire when performing certain actions or when observing another doing so; the brain's mirroring of another;s action may enable imitation and empathy.","sourceNumber":336},{"id":"appsych-unit-1-c63","front":"molecular genetics","back":"The subfield of biology that studies the molecular structure and functions of genes.","sourceNumber":341},{"id":"appsych-unit-1-c64","front":"motor cortex","back":"An area at the rear of the frontal lobes that controls voluntary movements.","sourceNumber":347},{"id":"appsych-unit-1-c65","front":"motor neurons","back":"Neurons that carry outgoing information from the brain and spinal cord to the muscles and glands.","sourceNumber":348},{"id":"appsych-unit-1-c66","front":"MRI (magnetic resonance imaging)","back":"A technique that uses  magnetic fields and radio waves to produce computer-generated images of soft tissue. Shows brain anatomy.","sourceNumber":349},{"id":"appsych-unit-1-c67","front":"myelin sheath","back":"A layer of fatty tissue segmentally encasing the  fibers of many neurons; enables vastly greater transmission speed of neural impulses as the pulse hops from one node to the next.","sourceNumber":351},{"id":"appsych-unit-1-c68","front":"narcolepsy","back":"A sleep disorder characterized by uncontrollable  sleep attacks. The sufferer may lapse directly into REM sleep, often at inopportune times 3.","sourceNumber":352},{"id":"appsych-unit-1-c69","front":"natural selection","back":"The principle that, among the range of inherited trait variations, those that lead to increased reproduction and survival will most likely be passed on to succeeding generations.","sourceNumber":354},{"id":"appsych-unit-1-c70","front":"near-death experience","back":"An altered state of consciousness reported after a close brush with death (such as through cardiac arrest); often similar to drug-induced hallucinations 3.","sourceNumber":357},{"id":"appsych-unit-1-c71","front":"nerves","back":"Bundled axons that form neural cables connecting the central nervous system with muscles, glands, and sense of organs. 3.","sourceNumber":359},{"id":"appsych-unit-1-c72","front":"nervous system","back":"The body's speedy electrochemical communication network, consisting of all the nerve cells of the peripheral and central nervous systems. 3.","sourceNumber":360},{"id":"appsych-unit-1-c73","front":"neuron","back":"A nerve cell; the basic building block of the nervous system.","sourceNumber":362},{"id":"appsych-unit-1-c74","front":"neurotransmitters","back":"Chemical messengers that cross the synaptic gaps between neurons. When released by the sending neuron, neurotransmitters travel across the synapse and bind to the receptor sites on the receiving neuron, thereby influencing whether that neuron will generate a neural impulse.","sourceNumber":363},{"id":"appsych-unit-1-c75","front":"night terrors","back":"A sleep disorder characterized by high arousal and an appearance of being terrified; unlike nightmares, night terrors occur during Stage  sleep, within two or three hours of falling asleep, and are seldom remembered.","sourceNumber":364},{"id":"appsych-unit-1-c76","front":"NREM sleep","back":"Non-rapid eye movement sleep; encompasses all sleep stages except for REM sleep.","sourceNumber":369},{"id":"appsych-unit-1-c77","front":"occipital lobes","back":"Portion of the cerebral cortex lying at the back of the head; includes areas that receive information from the visual fields.","sourceNumber":373},{"id":"appsych-unit-1-c78","front":"opiates","back":"Opium and its derivatives, such as morphine and heroin; they depress neural activity, temporarily lessening pain and anxiety.","sourceNumber":380},{"id":"appsych-unit-1-c79","front":"opponent-process theory","back":"The theory that opposing retinal processes (red-green, yellow-blue, white-black) enable color vision. For example, some cells are stimulated by green and inhibited by red; others are stimulated by red and inhibited by  green.","sourceNumber":381},{"id":"appsych-unit-1-c80","front":"optic nerve","back":"The nerve that carries neural impulses from the eye to the brain 3.","sourceNumber":382},{"id":"appsych-unit-1-c81","front":"parallel processing","back":"The processing of several aspects of a  problem simultaneously; the brain's natural mode of information processing for many functions, including vision. Contrasts with the step-by-step (serial) processing of most computers and of conscious problem solving.","sourceNumber":388},{"id":"appsych-unit-1-c82","front":"parasympathetic nervous system","back":"The division of the autonomic nervous system that calms the body, conserving its energy.","sourceNumber":390},{"id":"appsych-unit-1-c83","front":"parietal lobes","back":"Portion of the cerebral cortex lying at the top of the head and toward the rear; receives sensory input for touch and body position.","sourceNumber":391},{"id":"appsych-unit-1-c84","front":"peripheral nervous system (PNS)","back":"The sensory and motor neurons that connect the central nervous system (CNS) to the rest of the body.","sourceNumber":398},{"id":"appsych-unit-1-c85","front":"PET (positron emission tomography) scan","back":"A visual display of brain activity that detects where a radioactive form of glucose goes while the brain performs a given task.","sourceNumber":406},{"id":"appsych-unit-1-c86","front":"physical dependence","back":"A physiological need for a drug, marked by unpleasant withdrawal symptoms when the drug is discontinued.","sourceNumber":410},{"id":"appsych-unit-1-c87","front":"pituitary gland","back":"The endocrine system's most influential gland. Under the influence of the hypothalamus, the pituitary regulates growth and controls other endocrine glands.","sourceNumber":412},{"id":"appsych-unit-1-c88","front":"place theory","back":"In hearing, the theory that links the pitch we hear with the place where the cochlea's membrane is stimulated.","sourceNumber":413},{"id":"appsych-unit-1-c89","front":"plasticity","back":"The brain's ability to change, especially during childhood, by reorganizing after damage or by building new pathways based on experience.","sourceNumber":415},{"id":"appsych-unit-1-c90","front":"psychoactive drug","back":"A chemical substance that alters perceptions and moods.","sourceNumber":436},{"id":"appsych-unit-1-c91","front":"psychological dependence","back":"A psychological need to use a drug, such as to relieve negative emotions.","sourceNumber":441},{"id":"appsych-unit-1-c92","front":"psychosurgery","back":"Surgery that removes or destroys brain tissue in an effort to change behavior.","sourceNumber":450},{"id":"appsych-unit-1-c93","front":"pupil","back":"The adjustable opening in the center of the eye through which light enters.","sourceNumber":454},{"id":"appsych-unit-1-c94","front":"reflex","back":"A simple automatic response to a sensory stimulus, such as the knee-jerk response. 4.","sourceNumber":464},{"id":"appsych-unit-1-c95","front":"refractory period","back":"A resting period after orgasm, during which a man cannot achieve another orgasm.","sourceNumber":465},{"id":"appsych-unit-1-c96","front":"REM rebound","back":"The tendency for REM sleep to increase following REM sleep deprivation (created by repeated awakenings during REM sleep).","sourceNumber":473},{"id":"appsych-unit-1-c97","front":"REM sleep","back":"Rapid eye movement sleep; a recurring sleep stage during which vivid dreams commonly occur. Also known as paradoxical sleep, because the muscles are relaxed (except for minor twitches) but other body systems are active.","sourceNumber":474},{"id":"appsych-unit-1-c98","front":"reticular formation","back":"A nerve network in the brainstem that plays an important role in controlling arousal.","sourceNumber":483},{"id":"appsych-unit-1-c99","front":"retina","back":"The light-sensitive inner surface of the eye, containing the receptor rods and cones plus layers of neurons that begin the processing of visual information.","sourceNumber":484},{"id":"appsych-unit-1-c100","front":"retinal disparity","back":"A binocular cue for perceiving depth; by comparing images from the two eyeballs, the brain computes distance - the greater the disparity (difference) between the two images, the closer the object.","sourceNumber":485},{"id":"appsych-unit-1-c101","front":"reuptake","back":"A neurotransmitter's reabsorption by the sending neuron.","sourceNumber":488},{"id":"appsych-unit-1-c102","front":"rods","back":"Retinal receptors that detect black, white, and gray; necessary for peripheral and twilight vision, when cones don't respond.","sourceNumber":489},{"id":"appsych-unit-1-c103","front":"sensation","back":"The faculty through which the external world is apprehended.","sourceNumber":510},{"id":"appsych-unit-1-c104","front":"sensorieneural hearing loss","back":"Hearing impairment caused by  lesions or dysfunction of the cochlea or auditory nerve.","sourceNumber":511},{"id":"appsych-unit-1-c105","front":"sensorimotor stage","back":"In Piaget's theory, the stage (from birth to about  years of age) during which infants know the world mostly in terms of their sensory impressions and motor acitvities.","sourceNumber":512},{"id":"appsych-unit-1-c106","front":"sensory adaptation","back":"Diminished sensitivity as a consequence of constant stimulation.","sourceNumber":513},{"id":"appsych-unit-1-c107","front":"sensory cortex","back":"Area at the front of the parietal lobes that registers and processes body touch and movement sensations.","sourceNumber":514},{"id":"appsych-unit-1-c108","front":"sensory interaction","back":"The principle that one sense may influence another, as when the smell of food influences its taste.","sourceNumber":515},{"id":"appsych-unit-1-c109","front":"sensory neurons","back":"Neurons that carry incoming information from the sensory receptors to the brain and spinal cord.","sourceNumber":517},{"id":"appsych-unit-1-c110","front":"signal detection theory","back":"A theory predicting how and when we detect the presence of a faint stimulus (\"Signal\") amid background stimulation (\"Noise\"). Assumes there is no single absolute threshold and detection depends partly on a person's experience, expectations, motivation, and level of fatigue.","sourceNumber":524},{"id":"appsych-unit-1-c111","front":"Sleep","back":"Periodic, natural loss of consciousness--as distinct from unconsciousness resulting from a coma, general anesthesia, or hibernation.","sourceNumber":525},{"id":"appsych-unit-1-c112","front":"sleep apnea","back":"A sleep disorder characterized by temporary cessations of breathing during sleep and repeated momentary awakenings.","sourceNumber":526},{"id":"appsych-unit-1-c113","front":"somatic nervous system","back":"The division of the peripheral nervous system that controls the body's skeletal muscles. Also called the skeletal nervous system.","sourceNumber":539},{"id":"appsych-unit-1-c114","front":"split brain","back":"A condition resulting from surgery that isolates the brain's two hemispheres by cutting the fibers (mainly those of the corpus callosum connecting them).","sourceNumber":543},{"id":"appsych-unit-1-c115","front":"stimulants","back":"Drugs (such as caffeine, nicotine, and the more powerful amphetamines, cocaine, and Ecstacy) that excite neural activity and speed up body functions.","sourceNumber":553},{"id":"appsych-unit-1-c116","front":"sympathetic nervous system","back":"The division of the autonomic nervous system that arouses the body, mobilizing its energy in stressful situations.","sourceNumber":563},{"id":"appsych-unit-1-c117","front":"synapse","back":"The junction between the axon tip of the sending neuron and the dendrite or cell body of the receiving neuron. The tiny gap at the junction is called the synaptic gap or synaptic cleft.","sourceNumber":564},{"id":"appsych-unit-1-c118","front":"temporal lobes","back":"Portion of the cerebral cortex lying roughly above the ears; includes the auditory areas, each receiving information primarily from the opposite ear.","sourceNumber":570},{"id":"appsych-unit-1-c119","front":"thalamus","back":"The brain's sensory switchboard, located on top of the brainstem; it directs messages to the sensory reviving areas in the cortex and transmits replies to the cerebellum and  medulla.","sourceNumber":575},{"id":"appsych-unit-1-c120","front":"THC","back":"The major active ingredient in marijuana; triggers a variety of effects, including mild hallucinations.","sourceNumber":576},{"id":"appsych-unit-1-c121","front":"tolerance","back":"The diminishing effect with regular use of the same  dose of a drug, requiring the user to take larger and larger doses before experiencing the drug's effect 6.","sourceNumber":582},{"id":"appsych-unit-1-c122","front":"transduction","back":"Conversion of one form of energy into another.  In sensation, the transforming of stimulus energies, such as sights, sounds, and smells, into neural impulses our brains can interpret. 6.","sourceNumber":585},{"id":"appsych-unit-1-c123","front":"vestibular sense","back":"A sensory system located in structures of the inner ear that registers the orientation of the head.","sourceNumber":599},{"id":"appsych-unit-1-c124","front":"wavelength","back":"The distance between crests of waves, such as those of the electromagnetic spectrum.","sourceNumber":603},{"id":"appsych-unit-1-c125","front":"Weber's law","back":"The principle that, to be perceived as different, two stimuli must differ by a constant minimum percentage (rather than a constant amount).","sourceNumber":604},{"id":"appsych-unit-1-c126","front":"Wernicke's area","back":"Controls language reception - a brain area involved in language comprehension and expression; usually in the left temporal lobes.","sourceNumber":607},{"id":"appsych-unit-1-c127","front":"withdrawal","back":"The discomfort and distress that follow discontinuing the use of an addictive drug.","sourceNumber":608},{"id":"appsych-unit-1-c128","front":"X chromosome","back":"The sex chromosome found in both men and women; females have two & males have one; one from each parent produces a female child.","sourceNumber":610},{"id":"appsych-unit-1-c129","front":"Y chromosome","back":"The sex chromosome found only in males; when paired with an X chromosome from the mother, it produces a male child.","sourceNumber":611},{"id":"appsych-unit-1-c130","front":"Young-Helmholtz trichromatic theory","back":"Retina contains three diff color receptors (blue green red).","sourceNumber":612}],"questions":[],"feynmanPrompts":[{"id":"appsych-unit-1-f1","prompt":"Neural communication"},{"id":"appsych-unit-1-f2","prompt":"The nervous and endocrine systems"},{"id":"appsych-unit-1-f3","prompt":"Brain structure and function"},{"id":"appsych-unit-1-f4","prompt":"Heredity and environment"},{"id":"appsych-unit-1-f5","prompt":"Sleep and circadian rhythms"},{"id":"appsych-unit-1-f6","prompt":"Sensation and transduction"},{"id":"appsych-unit-1-f7","prompt":"Psychoactive drugs and dependence"}]},{"id":"appsych-unit-2","name":"AP Psychology - Unit 2","shortName":"Unit 2: Cognition","builtIn":true,"sourceTitle":"Myer's Psychology for AP Vocabulary","sourceUrl":"https://www.bpsgroverteacher.com/uploads/1/4/8/4/14847764/myer_s_psychology_for_ap_vocab.pdf","cedTitle":"AP Psychology Course and Exam Description - Effective Fall 2025","cedUrl":"https://apcentral.collegeboard.org/media/pdf/ap-psychology-course-and-exam-description.pdf","cards":[{"id":"appsych-unit-2-c1","front":"achievement tests","back":"Tests designed to assess what a person has learned.","sourceNumber":4},{"id":"appsych-unit-2-c2","front":"acoustic encoding","back":"The encoding of sound, especially the sound of words.","sourceNumber":6},{"id":"appsych-unit-2-c3","front":"algorithm","back":"A methodical, logical rule or procedure that guarantees solving a particular problems. contrasts with the usually speedier - but also more error-prone-use of heuristics.","sourceNumber":16},{"id":"appsych-unit-2-c4","front":"aphasia","back":"Impairment of language, usually caused by left hemisphere damage either to Broca's area (impairing speaking) or to Wernicke's area (impairing understanding).","sourceNumber":28},{"id":"appsych-unit-2-c5","front":"aptitude tests","back":"Tests designed to predict a person's future performance; aptitude is the capacity to learn.","sourceNumber":30},{"id":"appsych-unit-2-c6","front":"association areas","back":"Areas of the cerebral cortex that are not involved in primary motor or sensory functions; rather, they are involved in higher mental functions such as learning, remembering, thinking , and speaking.","sourceNumber":32},{"id":"appsych-unit-2-c7","front":"automatic processing","back":"Unconscious encoding of incidental information, such as space time, and frequency, and of well- learned information, such as word meanings. 5.","sourceNumber":40},{"id":"appsych-unit-2-c8","front":"availability heuristic","back":"Estimating the likelihood of events based on their availability in memory; if instances come readily  to mind (perhaps because of their vividness), we presume such events are common 6.","sourceNumber":42},{"id":"appsych-unit-2-c9","front":"basal metabolic rate","back":"The body's resting rate of energy  expenditure.","sourceNumber":47},{"id":"appsych-unit-2-c10","front":"belief perseverance","back":"Clinging to one's initial conceptions after the basis on which they were formed has been discredited.","sourceNumber":56},{"id":"appsych-unit-2-c11","front":"binocular cues","back":"Depth cues, such as retinal disparity and convergence, that depend on the use of two eyes.","sourceNumber":58},{"id":"appsych-unit-2-c12","front":"bottom-up processing","back":"Analysis that begins with the sensory receptors and works up to the brain's integration of sensory information.","sourceNumber":66},{"id":"appsych-unit-2-c13","front":"Broca's area","back":"Controls language expression - an area, usually in the left frontal lobe, that directs the muscle movements involved in speech.","sourceNumber":68},{"id":"appsych-unit-2-c14","front":"cerebral cortex","back":"The intricate fabic of interconnected neural cells covering the cerebral hemispheres; the body's ultimate control and information-processing center.","sourceNumber":77},{"id":"appsych-unit-2-c15","front":"change blindness","back":"The tendency to fail to detect changes in any part of a scene to which we are not focusing our attention.","sourceNumber":78},{"id":"appsych-unit-2-c16","front":"chunking","back":"Organizing items into familiar, manageable units; often occurs automatically.","sourceNumber":80},{"id":"appsych-unit-2-c17","front":"cognition","back":"All the mental activities associated with thinking, knowing, remembering, and communicating.","sourceNumber":88},{"id":"appsych-unit-2-c18","front":"cognitive map","back":"A mental representation of the layout of one's environment. for example, after exploring a maze, rats act as if they have learned this.","sourceNumber":91},{"id":"appsych-unit-2-c19","front":"cognitive neuroscience","back":"The interdisciplinary study of the brain activity linked with cognition (including perception, thinking, memory, and language) 1.","sourceNumber":93},{"id":"appsych-unit-2-c20","front":"cognitive psychology","back":"The scientific study of all the mental activities associated with thinking, knowing, remembering, and communicating.","sourceNumber":94},{"id":"appsych-unit-2-c21","front":"collective unconscious","back":"Carl Jung's concept of a shared,  inherited reservoir of memory traces form our species' history.","sourceNumber":96},{"id":"appsych-unit-2-c22","front":"color constancy","back":"Perceiving familiar objects as having consistent color, even if changing illumination alters the wavelengths reflected by the object.","sourceNumber":98},{"id":"appsych-unit-2-c23","front":"concept","back":"A mental grouping of similar objects, events, ideas, or people.","sourceNumber":100},{"id":"appsych-unit-2-c24","front":"confirmation bias","back":"A tendency to search for information that supports our preconceptions and to ignore or distort contradictory evidence.","sourceNumber":107},{"id":"appsych-unit-2-c25","front":"conflict","back":"A perceived incompatibility of actions, goals, or ideas.","sourceNumber":108},{"id":"appsych-unit-2-c26","front":"Consciousness","back":"Our awareness of ourselves and our environment.","sourceNumber":111},{"id":"appsych-unit-2-c27","front":"creativity","back":"The ability to produce novel and valuable ideas 1.","sourceNumber":124},{"id":"appsych-unit-2-c28","front":"critical thinking","back":"Thinking that does not blindly accept arguments and conclusions. Rather, it examines assumptions, discerns hidden values, evaluates evidence, and assesses  conclusions.","sourceNumber":126},{"id":"appsych-unit-2-c29","front":"crystallized intelligence","back":"Our accumulated knowledge and verbal skills; tends to increase with age 1.","sourceNumber":128},{"id":"appsych-unit-2-c30","front":"deja vu","back":"The eerie sense that\"I've experienced this before.\" Cues from the current situation may subconsciously trigger retrieval of an earlier experience.","sourceNumber":135},{"id":"appsych-unit-2-c31","front":"depth perception","back":"The ability to see objects in three dimensions although the images that strike the retina are two- dimensional; allows us to judge distance.","sourceNumber":142},{"id":"appsych-unit-2-c32","front":"dissociation","back":"A split in consciousness, which allows some thoughts and behaviors to occur simultaneously with others.","sourceNumber":150},{"id":"appsych-unit-2-c33","front":"Donald Meichenbaum","back":"Offered stress inoculation training: teaching people to restructure their thinking in stressful situations.","sourceNumber":154},{"id":"appsych-unit-2-c34","front":"dual processing","back":"The principle that information is often  simultaneously processed on separate conscious and unconscious tracks. 1.","sourceNumber":160},{"id":"appsych-unit-2-c35","front":"echoic memory","back":"A momentary sensory memory of auditory stimuli; if attention is elsewhere, sounds and words can still be recalled within  or  seconds.","sourceNumber":161},{"id":"appsych-unit-2-c36","front":"effortful processing","back":"Encoding that requires attention and conscious effort.","sourceNumber":165},{"id":"appsych-unit-2-c37","front":"emerging adulthood","back":"For some people on modern cultures, a period from the late teens to mid-twenties bridging the gap between adolescent dependence and full independence and responsible adulthood.","sourceNumber":171},{"id":"appsych-unit-2-c38","front":"emotional intelligence","back":"The ability to perceive, understand, manage, and use emotions.","sourceNumber":173},{"id":"appsych-unit-2-c39","front":"encoding","back":"The processing of information into the memory system.","sourceNumber":176},{"id":"appsych-unit-2-c40","front":"evolutionary psychology","back":"The study of the roots of behavior and mental processes using the principles of natural selection.","sourceNumber":183},{"id":"appsych-unit-2-c41","front":"explicit memory","back":"Memory of facts and experiences that one can consciously know and \"declare\" (declarative memory).","sourceNumber":188},{"id":"appsych-unit-2-c42","front":"feel-good, do-good phenomenon","back":"People's tendency to be  helpful when already in a good mood.","sourceNumber":198},{"id":"appsych-unit-2-c43","front":"fetal alcohol syndrome (FAS)","back":"Physical and cognitive abnormalities in children caused by a pregnant woman's heavy  drinking; in severe cases, symptoms include noticeable facial misproportions 2.","sourceNumber":199},{"id":"appsych-unit-2-c44","front":"fetus","back":"The developing human organism from  weeks after conception to birth.","sourceNumber":200},{"id":"appsych-unit-2-c45","front":"figure ground","back":"The organization of the visual field into objects  (the figures) that stand out from their surroundings (the ground).","sourceNumber":201},{"id":"appsych-unit-2-c46","front":"fixation","back":"According to Freud, a lingering focus of pleasure- seeking energies at an earlier psychosexual stage, in which conflicts were unresolved.","sourceNumber":203},{"id":"appsych-unit-2-c47","front":"flashbulb memory","back":"A clear memory of an emotionally  significant moment or event.","sourceNumber":206},{"id":"appsych-unit-2-c48","front":"fluid intelligence","back":"Our ability to reason speedily and  abstractly; tends to decrease during late adulthood.","sourceNumber":207},{"id":"appsych-unit-2-c49","front":"foot in the door technique","back":"The tendency for people who have agreed to a small request to comply later with a larger request.","sourceNumber":209},{"id":"appsych-unit-2-c50","front":"framing","back":"The way an issue is posed; can affect decisions and judgements.","sourceNumber":212},{"id":"appsych-unit-2-c51","front":"frequency","back":"The number of complete waves that pass a given point in a certain amount of time.","sourceNumber":215},{"id":"appsych-unit-2-c52","front":"functional fixedness","back":"The tendency to think of things only in terms of their usual functions; an impediment to problem solving.","sourceNumber":219},{"id":"appsych-unit-2-c53","front":"functionalism","back":"A school of psychology that focused on how our mental and behavioral processes function-how they enable us to adapt, survive and flourish.","sourceNumber":220},{"id":"appsych-unit-2-c54","front":"gender role","back":"A set of expected behavior for males or for females.","sourceNumber":225},{"id":"appsych-unit-2-c55","front":"gender typing","back":"The acquisition of a traditional masculine or feminine role.","sourceNumber":226},{"id":"appsych-unit-2-c56","front":"general intelligence","back":"A general intelligence factor that, according to Spearman and others, underlies specific mental abilities and is therefore measured by every task on an intelligence test.","sourceNumber":228},{"id":"appsych-unit-2-c57","front":"generalization","back":"The tendency, once a response has been conditioned, for a stimuli similar to the conditioned stimulus to elicit similar responses.","sourceNumber":229},{"id":"appsych-unit-2-c58","front":"gestalt","back":"An organized whole. Gestalt psychologists emphasized our tendency to integrate pieces of information into meaningful wholes.","sourceNumber":233},{"id":"appsych-unit-2-c59","front":"glucose","back":"The form of sugar that circulates in the blood and provides the major source of energy for body tissues; when its level is low, we feel hunger.","sourceNumber":235},{"id":"appsych-unit-2-c60","front":"grammar","back":"In a language, a system of rules that enables us to communicate with and understand others.","sourceNumber":236},{"id":"appsych-unit-2-c61","front":"GRIT","back":"Strategy designed to decrease international tensions.","sourceNumber":237},{"id":"appsych-unit-2-c62","front":"heritablity","back":"The proportion of variation among individuals that we can attribute to genes. This may vary, depending on the range of populations and environments studied. 2.","sourceNumber":245},{"id":"appsych-unit-2-c63","front":"heuristic","back":"A simple thinking strategy that often allows us to make judgements and solve problems efficiently; usually speedier  but also more error-prone than algorithms.","sourceNumber":246},{"id":"appsych-unit-2-c64","front":"hierarchy of neds","back":"Maslow's pyramid of human needs, beginning at the base with physiological needs that must first be satisfied before higher-level safety needs and then psychological needs become active.","sourceNumber":247},{"id":"appsych-unit-2-c65","front":"homeostasis","back":"A tendency to maintain a balanced or constant internal state; the regulation of any aspect of body chemistry, such as blood glucose, around a particular level.","sourceNumber":251},{"id":"appsych-unit-2-c66","front":"hue","back":"The dimension of color that is determined by the wavelength of light; what we know as the color names blue, green, and so forth.","sourceNumber":253},{"id":"appsych-unit-2-c67","front":"human factors psychology","back":"The study of how people and machines interact and the design of safe and easily used machines and environments.","sourceNumber":254},{"id":"appsych-unit-2-c68","front":"humanistic psychology","back":"Historically significant perspective that emphasized the growth potential of healthy people and individual's potential for fostering personal growth.","sourceNumber":255},{"id":"appsych-unit-2-c69","front":"hypnosis","back":"A social interaction in which one person (the hypnotist) suggests to another (the subject) that certain perceptions, feelings, thoughts, or behaviors will spontaneously occur.","sourceNumber":256},{"id":"appsych-unit-2-c70","front":"iconic memory","back":"A momentary sensory memory of visual stimuli; a photographic or picture-image memory lasting no more than a few tenths of a second.","sourceNumber":260},{"id":"appsych-unit-2-c71","front":"identity","back":"Our sense of self; according to Erikson, the adolescent's task is to solidify a sense of self by testing and integrating various roles.","sourceNumber":264},{"id":"appsych-unit-2-c72","front":"imagery","back":"Mental pictures; a powerful aid to effortful processing, especially when combined with semantic encoding.","sourceNumber":266},{"id":"appsych-unit-2-c73","front":"implicit memory","back":"Retention independent of conscious recollection. (nondeclarative or procedural memory).","sourceNumber":267},{"id":"appsych-unit-2-c74","front":"inattentional blindness","back":"Failing to see visible objects when our attention is directed elsewhere 2.","sourceNumber":269},{"id":"appsych-unit-2-c75","front":"incentive","back":"A positive or negative environmental stimulus that motivates behavior 2.","sourceNumber":270},{"id":"appsych-unit-2-c76","front":"industrial organization (I/O) psychology","back":"The application  of psychological concepts and methods to optimizing human behavior in workplaces.","sourceNumber":273},{"id":"appsych-unit-2-c77","front":"insight therapies","back":"A variety of therapies that aim to improve psychological functioning by increasing the client's awareness of underlying motives and defenses 3.","sourceNumber":281},{"id":"appsych-unit-2-c78","front":"intellectual disability","back":"(formerly referred to as mental retardation) a condition of limited mental ability, indicated by an intelligence score of 70 or below and difficulty in adapting to the demands of life; varies from mild to profound. 3.","sourceNumber":284},{"id":"appsych-unit-2-c79","front":"intelligence","back":"Mental quality consisting of the ability to learn from experience, solve problems, and use knowledge to adapt to new situations. 3.","sourceNumber":285},{"id":"appsych-unit-2-c80","front":"intelligence quotient (IQ)","back":"Defined originally as the ratio of mental age (ma) to chronological age (ca) multiplied by 100 (thus, IQ=ma/ca x 100). On contemporary intelligence test, the average performance for a given age is assigned a score of 100.","sourceNumber":286},{"id":"appsych-unit-2-c81","front":"intelligence test","back":"A method for assessing an individual's mental aptitudes and comparing them with those of others, using numerical scores.","sourceNumber":287},{"id":"appsych-unit-2-c82","front":"intensity","back":"The amount of energy in a light or sound wave, which we perceive as brightness or loudness, as determined by the wave's amplitude.","sourceNumber":288},{"id":"appsych-unit-2-c83","front":"interaction","back":"The interplay that occurs when the effect of one factor (such as environment) depends on another factor (such as heredity).","sourceNumber":289},{"id":"appsych-unit-2-c84","front":"interpretation","back":"In psychoanalysis, the analyst's noting supposed dream meanings, resistances, and other significant behaviors and events in order to promote insight.","sourceNumber":292},{"id":"appsych-unit-2-c85","front":"intuition","back":"An effortless, immediate, automatic feeling or thought, as contrasted with explicit, conscious reasoning.","sourceNumber":295},{"id":"appsych-unit-2-c86","front":"iris","back":"A ring of muscle tissue that forms the colored portion of the eye around the pupil and controls the size of the pupil opening.","sourceNumber":296},{"id":"appsych-unit-2-c87","front":"just world phenomenon","back":"Tendency for people to believe the world is just and that people therefore get what they deserve and deserve what they get.","sourceNumber":298},{"id":"appsych-unit-2-c88","front":"kinesthesis","back":"The system for sensing the position and movement of individual body parts.","sourceNumber":299},{"id":"appsych-unit-2-c89","front":"language","back":"Our spoken, written, or signed words and the ways we combine them to communicate meaning.","sourceNumber":300},{"id":"appsych-unit-2-c90","front":"linguistic determinism","back":"Whorf's hypothesis that language determines the way we think.","sourceNumber":310},{"id":"appsych-unit-2-c91","front":"long-term memory","back":"The relatively permanent and limitless  storehouse of the memory system; includes knowledge, skills, and experiences 3.","sourceNumber":312},{"id":"appsych-unit-2-c92","front":"long-term potentiation","back":"An increase in a synapse's firing potential after brief, rapid stimulation. Believed to be a neural basis for learning and memory.","sourceNumber":313},{"id":"appsych-unit-2-c93","front":"lymphocytes","back":"The two types of white blood cells that are part of the body's immune system: B lymphocytes form in the bone marrow and release antibodies that fight bacterial infections; T lymphocytes form in the thymus and other lymphatic tissue and attack cancer cells, viruses, and foreign substances.","sourceNumber":316},{"id":"appsych-unit-2-c94","front":"memory","back":"The persistence of learning over time through the storage and retrieval of information.","sourceNumber":325},{"id":"appsych-unit-2-c95","front":"menemonics","back":"Memory aids, especially those techniques that use vivid imagery and organizational devices.","sourceNumber":327},{"id":"appsych-unit-2-c96","front":"menopause","back":"The time of natural cessation of menstruation; also refers to the biological changes a woman experiences as her ability to reproduce declines.","sourceNumber":328},{"id":"appsych-unit-2-c97","front":"mental age","back":"A measure of intelligence test performance devised by Binet; the chronological age that most typically corresponds to a given level of performance. Thus, a child who does as well as the average 8-year-old is said to have a mental age of.","sourceNumber":329},{"id":"appsych-unit-2-c98","front":"mental set","back":"A tendency to approach a problem in one particular way, often a way that has been successful in the past.","sourceNumber":330},{"id":"appsych-unit-2-c99","front":"mere-exposure effect","back":"The phenomenon that repeated exposure to novel stimuli increases liking of them.","sourceNumber":331},{"id":"appsych-unit-2-c100","front":"middle ear","back":"The chamber between the eardrum and cochlea containing three tiny bones (hammer, anvil, and stirrup) that concentrate the vibrations of the eardrum on the cochlea's oval window.","sourceNumber":334},{"id":"appsych-unit-2-c101","front":"mirror-image perceptions","back":"Mutual views often held by conflicting people, as when each side sees itself as ethical and peaceful and views the other side as evil and aggressive.","sourceNumber":337},{"id":"appsych-unit-2-c102","front":"misinformation effect","back":"Incorporating misleading information into one's memory of an event.","sourceNumber":338},{"id":"appsych-unit-2-c103","front":"monocular cues","back":"Depth cues, such as interposition and linear perspective, available to either eye alone.","sourceNumber":342},{"id":"appsych-unit-2-c104","front":"mood-congruent memory","back":"The tendency to recall experiences that are consistent with one's current good or bad mood.","sourceNumber":344},{"id":"appsych-unit-2-c105","front":"morpheme","back":"In a language, the smallest unit that carries meaning; may be a word or a part of a word (such as a prefix).","sourceNumber":345},{"id":"appsych-unit-2-c106","front":"mutation","back":"A random error in gene replication that leads to a change.","sourceNumber":350},{"id":"appsych-unit-2-c107","front":"object permanence","back":"The awareness that things continue to exist even when not perceived.","sourceNumber":370},{"id":"appsych-unit-2-c108","front":"operant behavior","back":"Behavior that operates on the environment, producing consequences.","sourceNumber":376},{"id":"appsych-unit-2-c109","front":"other race effect","back":"The tendency to recall faced of one's own race more accurately than faces of another race 4.","sourceNumber":383},{"id":"appsych-unit-2-c110","front":"overconfidence","back":"The tendency to be more confident than correct-to overestimate the accuracy of our beliefs and  judgements.","sourceNumber":385},{"id":"appsych-unit-2-c111","front":"parapsychology","back":"The study of paranormal phenomena, including ESP and psychokinesis.","sourceNumber":389},{"id":"appsych-unit-2-c112","front":"passionate love","back":"An aroused state of intense positive absorption in another, usually present at the beginning of a love  relationship.","sourceNumber":393},{"id":"appsych-unit-2-c113","front":"perception","back":"The process of organizing and interpreting sensory information, enabling us to recognize meaningful objects and events 4.","sourceNumber":394},{"id":"appsych-unit-2-c114","front":"perceptual adaptation","back":"In vision, the ability to adjust to an artificially displaced or even inverted visual field.","sourceNumber":395},{"id":"appsych-unit-2-c115","front":"perceptual consistency","back":"The perceptual stability of the size, shape, and brightness, and color for familiar objects seen at varying distances, different angles, and under different lighting conditions.","sourceNumber":396},{"id":"appsych-unit-2-c116","front":"perceptual set","back":"A mental predisposition to perceive one thing and not another.","sourceNumber":397},{"id":"appsych-unit-2-c117","front":"personal space","back":"The buffer-zone we like to maintain around our bodies.","sourceNumber":401},{"id":"appsych-unit-2-c118","front":"personality psychology","back":"The study of individual's characteristics patter of thinking, feeling, and acting.","sourceNumber":405},{"id":"appsych-unit-2-c119","front":"phi phenomenon","back":"An illusion of movement created when two or more adjacent lights blink on and off in quick succession.","sourceNumber":407},{"id":"appsych-unit-2-c120","front":"phoneme","back":"In language, the smallest distinctive sound unit.","sourceNumber":409},{"id":"appsych-unit-2-c121","front":"pitch","back":"A tone's highness or lowness; depends on frequency.","sourceNumber":411},{"id":"appsych-unit-2-c122","front":"Post-Traumatic Growth","back":"Positive psychological changes as a result of struggling with extremely challenging circumstances and life crises. 4.","sourceNumber":420},{"id":"appsych-unit-2-c123","front":"posthypnotic suggestion","back":"A suggestion, made during a hypnosis session, to be carried out after the subject is no longer hypnotized; used by some clincians to help control undesired symptoms and behaviors.","sourceNumber":422},{"id":"appsych-unit-2-c124","front":"preoperational stage","back":"In Piaget's theory, the stage (from about  to  or  years of age) during which a child learns to use language but does not yet comprehend the mental operations of  concrete logic 4.","sourceNumber":425},{"id":"appsych-unit-2-c125","front":"primary sex characteristics","back":"The body structures (ovaries, testes, and external genitalia) that make sexual reproduction possible) 4.","sourceNumber":427},{"id":"appsych-unit-2-c126","front":"priming","back":"The activation, often unconsciously, of certain associations, thus predisposing one's perception, memory, or response 4.","sourceNumber":429},{"id":"appsych-unit-2-c127","front":"proactive interference","back":"The disruptive effect of prior learning on the recall of new information.","sourceNumber":430},{"id":"appsych-unit-2-c128","front":"prototype","back":"A mental image or best example of a category. provides a quick and easy method for sorting items into categories.","sourceNumber":434},{"id":"appsych-unit-2-c129","front":"psychology","back":"The science of behavior and mental processes.","sourceNumber":443},{"id":"appsych-unit-2-c130","front":"psychoneuroimmunology","back":"The study of how psychological, neural, and endocrine processes together affect the immune system and resulting health.","sourceNumber":445},{"id":"appsych-unit-2-c131","front":"psychophysics","back":"The study of relationships between the physical characteristics of stimuli, such as their intensity, and our psychological experience of them.","sourceNumber":447},{"id":"appsych-unit-2-c132","front":"recall","back":"A measure of memory in which the person must retrieve information learned earlier, as on a fill-in-the-blank test.","sourceNumber":460},{"id":"appsych-unit-2-c133","front":"recognition","back":"A measure of memory in which the person need  only identify items previously learned, as on a multiple-choice test 4.","sourceNumber":463},{"id":"appsych-unit-2-c134","front":"rehearsal","back":"The conscious repetition of information, either to maintain it in consciousness or to encode it for storage. 4.","sourceNumber":468},{"id":"appsych-unit-2-c135","front":"relearning","back":"A measure of memory that assesses the amount of time saved when learning material for a second time 4.","sourceNumber":471},{"id":"appsych-unit-2-c136","front":"reliability","back":"The extent to which a test yields consistent results, as assessed by the consistency of scores on two halves of the test, or on retesting.","sourceNumber":472},{"id":"appsych-unit-2-c137","front":"representativeness heuristic","back":"Judging the likelihood of things in terms of how well they seem to represent, or match, particular prototypes; may lead us to ignore other relevant information.","sourceNumber":477},{"id":"appsych-unit-2-c138","front":"retrieval","back":"The process of getting information out of memory storage.","sourceNumber":486},{"id":"appsych-unit-2-c139","front":"retroactive interference","back":"The disruptive effect of new learning on the recall of old information.","sourceNumber":487},{"id":"appsych-unit-2-c140","front":"savant syndrome","back":"A condition in which a person otherwise  limited in mental ability has an exceptional specific skill, such as in computation or drawing. 5.","sourceNumber":493},{"id":"appsych-unit-2-c141","front":"schema","back":"A concept or framework that organizes and interprets  information.","sourceNumber":496},{"id":"appsych-unit-2-c142","front":"selective attention","back":"The focusing of conscious awareness on a particular stimulus, as in the cocktail party effect 5.","sourceNumber":499},{"id":"appsych-unit-2-c143","front":"semantic encoding","back":"The encoding of meaning, including the meaning of words.","sourceNumber":508},{"id":"appsych-unit-2-c144","front":"semantics","back":"The set of rules by which we derive meaning from  morphemes, words, and sentences in a given language; also the study of meaning 5.","sourceNumber":509},{"id":"appsych-unit-2-c145","front":"sensory memory","back":"The immediate, very brief recording of sensory information in the memory system.","sourceNumber":516},{"id":"appsych-unit-2-c146","front":"serial position effect","back":"Our tendency to recall best the last and first items in a list.","sourceNumber":518},{"id":"appsych-unit-2-c147","front":"set point","back":"The point at which an individual's \"weight thermostat\" is supposedly set; when the body falls below this weight, an increase in hunger and a lowered metabolic rate my act to restore the lost weight.","sourceNumber":519},{"id":"appsych-unit-2-c148","front":"sexual orientation","back":"An enduring sexual attraction toward members of either one's own sex (homosexual orientation) or the other sex (heterosexual orientation).","sourceNumber":520},{"id":"appsych-unit-2-c149","front":"sexual response cycle","back":"The four stages of sexual responding described by Masters and Johnson - excitement, plateau, orgasm, and resolution.","sourceNumber":521},{"id":"appsych-unit-2-c150","front":"short-term memory","back":"Activated memory that holds a few items briefly before the information is stored or forgotten.","sourceNumber":523},{"id":"appsych-unit-2-c151","front":"source amnesia","back":"Attributing to the wrong source an event we have experiences, heard about, read about, or imagined (source misattribution) the heart of many false memories.","sourceNumber":541},{"id":"appsych-unit-2-c152","front":"spacing effect","back":"The tendency for distributed study of practice to yield better long-term retention that is achieved through massed study or practice.","sourceNumber":542},{"id":"appsych-unit-2-c153","front":"spotlight effect","back":"Overestimating others' noticing and evaluating our appearance, performance, and blunder (as if we presume a spotlight shine on us).","sourceNumber":545},{"id":"appsych-unit-2-c154","front":"Stanford-Binet","back":"The widely used American revision (by Terman at Stanford University) of Binet's original intelligence test.","sourceNumber":549},{"id":"appsych-unit-2-c155","front":"storage","back":"The retention of encoded information over time.","sourceNumber":554},{"id":"appsych-unit-2-c156","front":"structuralism","back":"An early school of psychology that used introspection to explore the elemental structure of the human mind.","sourceNumber":557},{"id":"appsych-unit-2-c157","front":"subliminal","back":"Below one's absolute threshold for conscious awareness.","sourceNumber":559},{"id":"appsych-unit-2-c158","front":"syntax","back":"The rules for combining words into grammatically sensible sentences in a given language.","sourceNumber":565},{"id":"appsych-unit-2-c159","front":"Thematic Apperception Test (TAT)","back":"A projective test in  which people express their inner feelings and interests through the stories they make up about ambiguous scenes. 5.","sourceNumber":577},{"id":"appsych-unit-2-c160","front":"threshold","back":"The level of stimulation required to trigger a neural  impulse.","sourceNumber":580},{"id":"appsych-unit-2-c161","front":"Top-down processing","back":"Information processing guided by  higher-level mental processes, as when we construct perceptions drawing on our experience and expectations 6.","sourceNumber":583},{"id":"appsych-unit-2-c162","front":"Type B","back":"Friedman and Rosenman's term for easygoing, relaxed people.","sourceNumber":590},{"id":"appsych-unit-2-c163","front":"Wechsler Adult Intelligence Scale (WAIS)","back":"The most widely used intelligence test; contains verbal and performance (nonverbal) subtests.","sourceNumber":605},{"id":"appsych-unit-2-c164","front":"working memory","back":"A newer understanding of short-term memory that focuses on conscious, active processing of incoming auditory and visual-spatial information, and of information retrieved from long-term memory.","sourceNumber":609}],"questions":[],"feynmanPrompts":[{"id":"appsych-unit-2-f1","prompt":"Perceptual organization"},{"id":"appsych-unit-2-f2","prompt":"Attention and consciousness"},{"id":"appsych-unit-2-f3","prompt":"Encoding and storing memories"},{"id":"appsych-unit-2-f4","prompt":"Retrieval and forgetting"},{"id":"appsych-unit-2-f5","prompt":"Thinking and problem solving"},{"id":"appsych-unit-2-f6","prompt":"Language and cognition"},{"id":"appsych-unit-2-f7","prompt":"Intelligence and achievement testing"}]},{"id":"appsych-unit-3","name":"AP Psychology - Unit 3","shortName":"Unit 3: Development and Learning","builtIn":true,"sourceTitle":"Myer's Psychology for AP Vocabulary","sourceUrl":"https://www.bpsgroverteacher.com/uploads/1/4/8/4/14847764/myer_s_psychology_for_ap_vocab.pdf","cedTitle":"AP Psychology Course and Exam Description - Effective Fall 2025","cedUrl":"https://apcentral.collegeboard.org/media/pdf/ap-psychology-course-and-exam-description.pdf","cards":[{"id":"appsych-unit-3-c1","front":"Accommodation (Piaget)","back":"Adapting our current understandings (schemas) to incorporate new information.","sourceNumber":3},{"id":"appsych-unit-3-c2","front":"acquisition","back":"In classical conditioning, the initial stage, when one links a neutral stimulus and an unconditioned stimulus so that the neutral stimulus begins triggering the conditioned response. in operant conditioning, the strengthening of a reinforced response.","sourceNumber":7},{"id":"appsych-unit-3-c3","front":"adolescence","back":"The transition period from childhood to adulthood, extending from puberty to independence.","sourceNumber":12},{"id":"appsych-unit-3-c4","front":"assimilation","back":"Interpreting our new experiences in terms of our existing schemas.","sourceNumber":31},{"id":"appsych-unit-3-c5","front":"associative learning","back":"Learning that certain events occur together. the events may be two stimuli (as in classical conditioning) or a response and its consequences (as in operant conditioning).","sourceNumber":33},{"id":"appsych-unit-3-c6","front":"attachment","back":"An emotional tie with another person; shown in young children by their seeking closeness to the caregiver and showing distress on separation.","sourceNumber":34},{"id":"appsych-unit-3-c7","front":"autism","back":"A disorder that appears in childhood and is marked by deficient communication, social interaction, and understanding of others' states of minds.","sourceNumber":39},{"id":"appsych-unit-3-c8","front":"babbling stage","back":"Beginning at about  months, the stage of speech development in which the infant spontaneously utters  various sounds at first unrelated to the household language.","sourceNumber":45},{"id":"appsych-unit-3-c9","front":"basic trust","back":"According to Erik Erikson, a sense that the world is predictable and trustworthy; said to be formed during infancy by appropriate experiences with responsive caregivers 6.","sourceNumber":49},{"id":"appsych-unit-3-c10","front":"behavioral psychology","back":"The scientific study of observable  behavior, and its explanation by principles of learning.","sourceNumber":53},{"id":"appsych-unit-3-c11","front":"classical conditioning","back":"A type of learning in which one learns to link two or more stimuli and anticipate events.","sourceNumber":82},{"id":"appsych-unit-3-c12","front":"concrete operational stage","back":"In Piaget's theory, the stage of cognitive development (from about  or  to 11 years of age) during which children gain the mental operations that enable them to think logically about concrete events.","sourceNumber":101},{"id":"appsych-unit-3-c13","front":"conditioned reinforcer","back":"A stimulus that gains its reinforcing power through its association with a primary reinforcer; also known as a secondary reinforcer.","sourceNumber":102},{"id":"appsych-unit-3-c14","front":"conditioned response","back":"In classical conditioning, the learned response to a previously neutral stimulus.","sourceNumber":103},{"id":"appsych-unit-3-c15","front":"conditioned stimulus","back":"In classical conditioning, an originally irrelevant stimulus that, after association with an unconditioned stimulus, comes to trigger a conditioned response.","sourceNumber":104},{"id":"appsych-unit-3-c16","front":"conservation","back":"The principle (which Piaget believed to be a part of concrete operational reasoning) that properties such as mass, volume, and number remain the same despite changes in the forms of objects.","sourceNumber":113},{"id":"appsych-unit-3-c17","front":"continuous reinforcement","back":"Reinforcing the desired response every time it occurs.","sourceNumber":115},{"id":"appsych-unit-3-c18","front":"critical period","back":"An optimal period shortly after birth when an organism's exposure to certain stimuli or experience produces  proper development.","sourceNumber":125},{"id":"appsych-unit-3-c19","front":"developmental psychology","back":"A branch of psychology that studies physical, cognitive, and social change throughout the life span.","sourceNumber":143},{"id":"appsych-unit-3-c20","front":"Discrimination (classical conditioning)","back":"In classical conditioning, the learned ability to distinguish between a conditioned stimulus and stimuli that do not signal an unconditioned stimulus.","sourceNumber":147},{"id":"appsych-unit-3-c21","front":"discriminative stimulus","back":"In operant conditioning, a stimulus that elicits a response after association with reinforcement (in contrast to related stimuli not associated with reinforcement).","sourceNumber":148},{"id":"appsych-unit-3-c22","front":"educational psychology","back":"The study of how psychological processes affect and can enhance teaching and learning.","sourceNumber":164},{"id":"appsych-unit-3-c23","front":"egocentrism","back":"In Piaget's theory, the preoperational child's difficulty taking another's point of view.","sourceNumber":167},{"id":"appsych-unit-3-c24","front":"embryo","back":"The developing human organism from about  weeks after fertilization through the second month.","sourceNumber":170},{"id":"appsych-unit-3-c25","front":"extinction","back":"The diminishing of a conditioned response; occurs in classical conditioning when an unconditioned stimulus does not follow a conditioned stimulus; occurs in operant conditioning when a response is no longer reinforced 2.","sourceNumber":191},{"id":"appsych-unit-3-c26","front":"fixed-interval schedule","back":"In operant conditioning, a reinforcement schedule that reinforces a response only after a specified time has elapsed.","sourceNumber":204},{"id":"appsych-unit-3-c27","front":"fixed-ratio schedule","back":"In operant conditioning, a reinforcement schedule that reinforces a response only after a specified number of responses 2.","sourceNumber":205},{"id":"appsych-unit-3-c28","front":"formal operational stage","back":"In Piaget's theory, the stage of cognitive development (normally beginning about age 12) during which people begin to think logically about abstract concepts.","sourceNumber":210},{"id":"appsych-unit-3-c29","front":"habituation","back":"Decreasing responsiveness with repeated  stimulation; as infants gain familiarity with repeated exposure to a visual stimulus, their interest wanes and they look away sooner 2.","sourceNumber":240},{"id":"appsych-unit-3-c30","front":"higher-order conditioning","back":"A procedure in which the conditioned stimulus in one conditioning experience is paired with a new neutral stimulus, creating a second (often weaker) conditioned stimulus.","sourceNumber":248},{"id":"appsych-unit-3-c31","front":"identification","back":"The process by which, according to Freud, children incorporate their parents' values into their developing superegos.","sourceNumber":263},{"id":"appsych-unit-3-c32","front":"imprinting","back":"The process by which certain animals form attachments during a critical period very early in life.","sourceNumber":268},{"id":"appsych-unit-3-c33","front":"intimacy","back":"In Erikson's theory, the ability to form close, loving relationships; a primary developmental task in late adolescence and early adulthood.","sourceNumber":293},{"id":"appsych-unit-3-c34","front":"latent learning","back":"Learning that occurs but is not apparent until there is an incentive to demonstrate it.","sourceNumber":302},{"id":"appsych-unit-3-c35","front":"law of effect","back":"Thorndike's principle that behaviors followed by favorable consequences become more likely, and that behavior followed by unfavorable consequences become less likely.","sourceNumber":303},{"id":"appsych-unit-3-c36","front":"learning","back":"A relatively permanent change in an organism's behavior due to experience.","sourceNumber":305},{"id":"appsych-unit-3-c37","front":"maturation","back":"Biological growth processes that enable orderly changes in behavior, relatively uninfluenced by experience 3.","sourceNumber":320},{"id":"appsych-unit-3-c38","front":"modeling","back":"The process of observing and imitating a specific behavior.","sourceNumber":340},{"id":"appsych-unit-3-c39","front":"nature-nurture issue","back":"The longstanding controversy over the relative contributions that genes and experience make to the development of psychological traits and behaviors. Today's science sees traits and behaviors arising from the interaction of nature and nurture.","sourceNumber":356},{"id":"appsych-unit-3-c40","front":"negative reinforcement","back":"Increasing behaviors by stopping or reducing negative stimuli, such as shock; any stimulus that,  when removed after a response, strengthens the response (NOT punishment).","sourceNumber":358},{"id":"appsych-unit-3-c41","front":"observational learning","back":"Learning by observing others; also called social learning.","sourceNumber":371},{"id":"appsych-unit-3-c42","front":"one-word stage","back":"The stage in speech development, from about age  to , during which a child speaks mostly in single words.","sourceNumber":375},{"id":"appsych-unit-3-c43","front":"operant chamber","back":"In operant conditioning research, a chamber (also known as a Skinner box) containing a bar or key that an animal can manipulate to obtain a food or water reinforcer; attached devices record the animal;s rate of bar pressing or key pecking.","sourceNumber":377},{"id":"appsych-unit-3-c44","front":"operant conditioning","back":"A type of learning in which behavior is strengthened if followed by a reinforcer or diminished if followed by a punisher.","sourceNumber":378},{"id":"appsych-unit-3-c45","front":"partial (intermittent) reinforcement","back":"Reinforcing a response only part of the time; results in slower acquisition of s response but much greater resistance to extinction than does continuous reinorcement 4.","sourceNumber":392},{"id":"appsych-unit-3-c46","front":"positive reinforcement","back":"Increasing behaviors by presenting positive stimuli, such as food; any stimulus that, when presented  after a response, strengthens the response.","sourceNumber":419},{"id":"appsych-unit-3-c47","front":"primary reinforcer","back":"An innately reinforcing stimulus, such as one that satisfies a biological need 4.","sourceNumber":426},{"id":"appsych-unit-3-c48","front":"psychosexual stages","back":"The childhood stages of development (oral, anal, phallic, latency, genital) during which, according to Freud, the id's pleasure-seeking energies focus on distinct erogenous zones.","sourceNumber":449},{"id":"appsych-unit-3-c49","front":"puberty","back":"The period of sexual maturation, during which a person becomes capable of reproducing.","sourceNumber":452},{"id":"appsych-unit-3-c50","front":"punishment","back":"An event that decreases the behavior that it follows.","sourceNumber":453},{"id":"appsych-unit-3-c51","front":"regression","back":"Psychoanalytic defense mechanism in which an  individual faced with anxiety retreats to a more infantile psychosexual stage, where some psychic energy remains fixated.","sourceNumber":466},{"id":"appsych-unit-3-c52","front":"reinforcer","back":"In operant conditioning, any event that strengthens the behavior it follows 4.","sourceNumber":469},{"id":"appsych-unit-3-c53","front":"respondent behavior","back":"Behavior that occurs as an automatic response to some stimulus.","sourceNumber":482},{"id":"appsych-unit-3-c54","front":"secondary sex characteristics","back":"Nonreproductive sexual characteristics, such as female breasts and hips, male voice  quality, and body hair.","sourceNumber":498},{"id":"appsych-unit-3-c55","front":"shaping","back":"An operant conditioning procedure in which reinforcers guide behavior toward closer and closer approximations of the desired behavior.","sourceNumber":522},{"id":"appsych-unit-3-c56","front":"social clock","back":"The culturally preferred timing of social events such as marriage, parenthood, and retirement.","sourceNumber":527},{"id":"appsych-unit-3-c57","front":"social learning theory","back":"The theory that we learn social behavior by observing and imitating and by being rewarded or punished.","sourceNumber":531},{"id":"appsych-unit-3-c58","front":"spontaneous recovery","back":"The reappearance, after a pause, of an extinguished conditioned response.","sourceNumber":544},{"id":"appsych-unit-3-c59","front":"stranger anxiety","back":"The fear of strangers that infants commonly display, beginning by about  months of age.","sourceNumber":555},{"id":"appsych-unit-3-c60","front":"telegraphic speech","back":"Early speech stage in which a child speaks like a telegram - go car\"- using mostly nouns and verbs.","sourceNumber":568},{"id":"appsych-unit-3-c61","front":"temperament","back":"A person's characteristic emotional reactivity and intensity.","sourceNumber":569},{"id":"appsych-unit-3-c62","front":"teratogens","back":"Agents, such as chemicals and viruses, that can reach the embryo or fetus during prenatal development and cause harm.","sourceNumber":571},{"id":"appsych-unit-3-c63","front":"testosterone","back":"The most important of the male sex hormones; both males and females have it, but the additional testosterone in males stimulates the growth of the male sex organs in the fetus and the development of the male sex characteristics during  puberty.","sourceNumber":573},{"id":"appsych-unit-3-c64","front":"theory of mind","back":"People's ideas about their own and others'  mental states -- about their feelings, perceptions, and thoughts, and the behaviors these might predict.","sourceNumber":579},{"id":"appsych-unit-3-c65","front":"two-word stage","back":"Beginning about age , the stage in speech  development during which a child speaks mostly two-word statements 6.","sourceNumber":588},{"id":"appsych-unit-3-c66","front":"unconditioned response","back":"In classical conditioning, the unlearned, naturally occurring response to the unconditioned stimulus, such as salivation when food is in the mouth.","sourceNumber":593},{"id":"appsych-unit-3-c67","front":"unconditioned stimulus","back":"In classical conditioning, a stimulus that unconditionally-naturally and automatically- triggers a response.","sourceNumber":594},{"id":"appsych-unit-3-c68","front":"variable-interval schedule","back":"In operant conditioning, a reinforcement schedule that reinforces a response at unpredictable time intervals.","sourceNumber":597},{"id":"appsych-unit-3-c69","front":"variable-ratio schedule","back":"In operant conditioning, a reinforcement schedule that reinforces a response after an unpredictable number of responses.","sourceNumber":598},{"id":"appsych-unit-3-c70","front":"visual cliff","back":"A laboratory device for testing depth perception in infants and young animals.","sourceNumber":601},{"id":"appsych-unit-3-c71","front":"zygote","back":"The fertilized egg; it enters a 2-week period of rapid cell division and develops into an embryo.","sourceNumber":613}],"questions":[],"feynmanPrompts":[{"id":"appsych-unit-3-f1","prompt":"Prenatal and physical development"},{"id":"appsych-unit-3-f2","prompt":"Cognitive development across the lifespan"},{"id":"appsych-unit-3-f3","prompt":"Social and emotional development"},{"id":"appsych-unit-3-f4","prompt":"Language development"},{"id":"appsych-unit-3-f5","prompt":"Classical conditioning"},{"id":"appsych-unit-3-f6","prompt":"Operant conditioning"},{"id":"appsych-unit-3-f7","prompt":"Observational and cognitive learning"}]},{"id":"appsych-unit-4","name":"AP Psychology - Unit 4","shortName":"Unit 4: Social Psychology and Personality","builtIn":true,"sourceTitle":"Myer's Psychology for AP Vocabulary","sourceUrl":"https://www.bpsgroverteacher.com/uploads/1/4/8/4/14847764/myer_s_psychology_for_ap_vocab.pdf","cedTitle":"AP Psychology Course and Exam Description - Effective Fall 2025","cedUrl":"https://apcentral.collegeboard.org/media/pdf/ap-psychology-course-and-exam-description.pdf","cards":[{"id":"appsych-unit-4-c1","front":"adaptation-level phenomenon","back":"Our tendency to form judgments (of sounds, of lights, of income) relative to a neutral level defined by our prior experience.","sourceNumber":10},{"id":"appsych-unit-4-c2","front":"aggression","back":"Any physical/verbal behavior intended to hurt or destroy.","sourceNumber":14},{"id":"appsych-unit-4-c3","front":"altruism","back":"Unselfish regard for the welfare of others.","sourceNumber":18},{"id":"appsych-unit-4-c4","front":"attitude","back":"Feelings, often influenced by our beliefs, that predispose us to response in a particular way to objects, people, and events.","sourceNumber":36},{"id":"appsych-unit-4-c5","front":"attribution theory","back":"Theory that we explain someone's behavior by crediting either the situation or the person's disposition.","sourceNumber":37},{"id":"appsych-unit-4-c6","front":"biopsychological approach","back":"An integrated approach that incorporates biological, psychological, and social-cultural levels of analysis.","sourceNumber":63},{"id":"appsych-unit-4-c7","front":"bystander effect","back":"Tendency for any given bystander to be less likely.","sourceNumber":70},{"id":"appsych-unit-4-c8","front":"Cannon-Bard theory","back":"The theory that an emotion-arousing stimulus simultaneously triggers (1) physiological responses and (2) the subjective experience of emotion.","sourceNumber":71},{"id":"appsych-unit-4-c9","front":"catharsis","back":"Emotional release; the catharsis hypothesis maintains that \"releasing\" aggressive energy (through action or fantasy) relieves aggressive urges.","sourceNumber":73},{"id":"appsych-unit-4-c10","front":"central route of persuasion","back":"Attitude change in which interested people focus on the actual argument and respond with favorable thoughts.","sourceNumber":75},{"id":"appsych-unit-4-c11","front":"cognitive dissonance theory","back":"Theory that we act to reduce the discomfort we feel when two of our thoughts are inconsistent; change our attitudes rather than our behaviors.","sourceNumber":90},{"id":"appsych-unit-4-c12","front":"collectivism","back":"Giving priority to the goals of one's group (often one's extended family or work group) and defining one's identity accordingly.","sourceNumber":97},{"id":"appsych-unit-4-c13","front":"companionate love","back":"The deep affectionate attachment we feel for those with whom our lives are intertwined.","sourceNumber":99},{"id":"appsych-unit-4-c14","front":"conformity","back":"Adjusting one's behavior/thinking to coincide with a group standard.","sourceNumber":109},{"id":"appsych-unit-4-c15","front":"culture","back":"The enduring behaviors, ideas, attitudes, and traditions shared by a group of people and transmitted form one generation to the next. 1.","sourceNumber":131},{"id":"appsych-unit-4-c16","front":"deindividuation","back":"The loss of self-awareness and self-restraint occurring in group situations that foster arousal or anonymity.","sourceNumber":134},{"id":"appsych-unit-4-c17","front":"Discrimination (social psychology)","back":"Unjustifiable negative behavior toward a group and its members.","sourceNumber":146},{"id":"appsych-unit-4-c18","front":"displacement","back":"Psychoanalytic defense mechanism that shifts sexual or aggressive impulses toward a more acceptable or less threatening object of person, as when redirecting anger toward a safer outlet.","sourceNumber":149},{"id":"appsych-unit-4-c19","front":"drive-reduction theory","back":"The idea that a physiological need creates an aroused tension state (a drive) that motivates an organism to satisfy the need 1.","sourceNumber":158},{"id":"appsych-unit-4-c20","front":"ego","back":"The largely conscious, \"executive\" part of personality that, according to Freud, mediates among the demands of the id, superego, and reality. The ego operates on the reality principle, satisfying the id's desires in ways that will realistically bring pleasure rather than pain.","sourceNumber":166},{"id":"appsych-unit-4-c21","front":"emotion","back":"A response of the whole organism, involving (1) physiological arousal, (2) expressive behaviors, and (3) conscious experience.","sourceNumber":172},{"id":"appsych-unit-4-c22","front":"empirically derived test","back":"A test (such as the MMPI) developed by testing a pool of items and then selecting those that discriminate between groups.","sourceNumber":174},{"id":"appsych-unit-4-c23","front":"equity","back":"A condition in which people receive from a relationship is proportional to what they give to it.","sourceNumber":180},{"id":"appsych-unit-4-c24","front":"external locus of control","back":"The perception that chance or outside forces beyond your personal control determine your fate.","sourceNumber":190},{"id":"appsych-unit-4-c25","front":"extrinsic motivation","back":"A desire to perform a behavior to receive  promised rewards or avoid threatened punishment.","sourceNumber":193},{"id":"appsych-unit-4-c26","front":"facial feedback","back":"The effect of facial expressions on experienced emotions, as when a facial expression of anger or happiness  intensifies feelings of anger or happiness.","sourceNumber":194},{"id":"appsych-unit-4-c27","front":"frustration-aggression principle","back":"The principle that frustration, the blocking of an attempt to achieve some goal, creates anger which can generate aggression.","sourceNumber":218},{"id":"appsych-unit-4-c28","front":"fundamental attribution error","back":"The tendency for observes, when analyzing another's behavior, to underestimate the impact of the situation and to overestimate the impact of personal disposition.","sourceNumber":221},{"id":"appsych-unit-4-c29","front":"gender","back":"In psychology, the biologically and socially influenced characteristics by which people define male and female.","sourceNumber":223},{"id":"appsych-unit-4-c30","front":"group polarization","back":"Tendency of group members to move to an extreme position after discussing an issue as a group.","sourceNumber":238},{"id":"appsych-unit-4-c31","front":"grouping","back":"The perceptual tendency to organize stimuli into coherent groups.","sourceNumber":239},{"id":"appsych-unit-4-c32","front":"id","back":"A reservoir of unconscious psychic energy that, according to Freud, strives to satisfy basic sexual and aggressive drives. the id operates on the pleasure principle, demanding immediate gratification.","sourceNumber":261},{"id":"appsych-unit-4-c33","front":"indicisualism","back":"Giving priority to one's own goals over group  goals and defining one's identity in therms of personal attributes rather than group identifications.","sourceNumber":272},{"id":"appsych-unit-4-c34","front":"informative social influence","back":"Influence resulting from one's  willingness to accept others' opinions about reality.","sourceNumber":274},{"id":"appsych-unit-4-c35","front":"ingroup","back":"Us; people with whom we share a common identity.","sourceNumber":276},{"id":"appsych-unit-4-c36","front":"insight","back":"A sudden and often novel realization of the solution to a problem; it contrasts with strategy-based solutions.","sourceNumber":279},{"id":"appsych-unit-4-c37","front":"instinct","back":"A complex behavior that is rigidly patterned throughout a species and is unlearned.","sourceNumber":283},{"id":"appsych-unit-4-c38","front":"internal locus of control","back":"The perception that you control your own fate.","sourceNumber":290},{"id":"appsych-unit-4-c39","front":"intrinsic motivation","back":"A desire to perform a behavior effectively for its own sake.","sourceNumber":294},{"id":"appsych-unit-4-c40","front":"James-Lange theory","back":"The theory that our experience of emotion is our awareness of our physiological responses to emotion-arousing stimuli.","sourceNumber":297},{"id":"appsych-unit-4-c41","front":"latent content","back":"According to Freud, the underlying meaning of a dream (as distinct from its manifest content).","sourceNumber":301},{"id":"appsych-unit-4-c42","front":"levels of analysis","back":"The differing complementary views, from biological to psychological to social-cultural, for analyzing any  given phenomenon.","sourceNumber":308},{"id":"appsych-unit-4-c43","front":"manifest content","back":"According to Freud, the remembered story line of a dream (as distinct from its latent, or hidden, content).","sourceNumber":319},{"id":"appsych-unit-4-c44","front":"Minnesota Multiphasic Personality Inventory (MMPI)","back":"The most widely researched and clinically used of all personality tests. Originally developed to identify emotional disorders (still considered its most appropriate use), this test is now used for many other screening purposes.","sourceNumber":335},{"id":"appsych-unit-4-c45","front":"motivation","back":"A need or desire that energizes and directs behavior.","sourceNumber":346},{"id":"appsych-unit-4-c46","front":"norm","back":"Understood rule for accepted/expected behavior.","sourceNumber":365},{"id":"appsych-unit-4-c47","front":"normative social influence","back":"Influence resulting from a person's desire to gain approval or avoid disapproval.","sourceNumber":368},{"id":"appsych-unit-4-c48","front":"Oedipus complex","back":"According to Freud, a boy's sexual desires toward his mother and feelings of jealousy and hatred for the rival father.","sourceNumber":374},{"id":"appsych-unit-4-c49","front":"outgroup","back":"Them; those perceived as different or apart from our ingroup 4.","sourceNumber":384},{"id":"appsych-unit-4-c50","front":"peripheral route of persuasion","back":"Attitude change in which people are influenced by incidental cues.","sourceNumber":399},{"id":"appsych-unit-4-c51","front":"personal control","back":"The extent to which people perceive control over their environment rather that feeling helpless.","sourceNumber":400},{"id":"appsych-unit-4-c52","front":"personality","back":"An individual's characteristic pattern of thinking, feeling, and acting.","sourceNumber":402},{"id":"appsych-unit-4-c53","front":"personality inventory","back":"A questionnaire (often with true-false or agree-disagree items) on which people respond to items designed to gauge a wide range of feelings and behaviors; used to assess selected personality traits.","sourceNumber":404},{"id":"appsych-unit-4-c54","front":"polygraph","back":"A machine, commonly used in attempts to detect lies, that measures several of the physiological responses accompanying emotion (such as perspiration and cardiovascular  and breathing changes).","sourceNumber":416},{"id":"appsych-unit-4-c55","front":"prejudice","back":"An unjustifiable attitude toward a group and its members; generally involved stereotyped beliefs.","sourceNumber":424},{"id":"appsych-unit-4-c56","front":"projection","back":"Psychoanalytic defense mechanism by which  people disguise their own threatening impulses by attributing them to others.","sourceNumber":431},{"id":"appsych-unit-4-c57","front":"projective test","back":"A personality test, such as the Rorschach or TAT, that provides ambiguous stimuli designed to trigger  projection of one'es inner dynamics.","sourceNumber":432},{"id":"appsych-unit-4-c58","front":"prosocial behavior","back":"Positive, constructive, helpful behavior; the opposite of antisocial behavior.","sourceNumber":433},{"id":"appsych-unit-4-c59","front":"psychometric","back":"The scientific study of the measurement of human abilities, attitudes, and traits.","sourceNumber":444},{"id":"appsych-unit-4-c60","front":"reciprocal determinism","back":"The interacting influences of  behavior, internal cognition, and environment.","sourceNumber":461},{"id":"appsych-unit-4-c61","front":"reciprocity norm","back":"An expectation that people will help, not  hurt, those who have helped them.","sourceNumber":462},{"id":"appsych-unit-4-c62","front":"relative deprivation","back":"The perception that we are worse off relative to those with whom we compare ourselves 4.","sourceNumber":470},{"id":"appsych-unit-4-c63","front":"role","back":"A set of expectations (norms) about a social position, defining how those in the position ought to behave.","sourceNumber":490},{"id":"appsych-unit-4-c64","front":"Rorschach inkblot test","back":"The most widely used projective test, a set of 10 inkblots, designed by Hermann Rorschach; seeks to identify people's inner feelings by analyzing their interpretations  of the blots.","sourceNumber":492},{"id":"appsych-unit-4-c65","front":"scapegoat theory","back":"The theory that prejudice offers an outlet for anger by providing someone to blame 5.","sourceNumber":494},{"id":"appsych-unit-4-c66","front":"self","back":"In contemporary psychology, assumed to be the center of personality, the organizer of our thoughts, feelings, and actions. 5.","sourceNumber":500},{"id":"appsych-unit-4-c67","front":"self-actualization","back":"According to Maslow, one of the ultimate psychological needs that arises after basic physical and psychological needs are met self-esteem is achieved; the motivation to fulfill one's potential.","sourceNumber":501},{"id":"appsych-unit-4-c68","front":"self-concept","back":"All our thoughts and feeling about ourselves, in  answer to the question, \"Who am I?\".","sourceNumber":502},{"id":"appsych-unit-4-c69","front":"self-disclosure","back":"Revealing intimate aspects of oneself to others.","sourceNumber":504},{"id":"appsych-unit-4-c70","front":"self-esteem","back":"One's feelings of high or low self worth.","sourceNumber":505},{"id":"appsych-unit-4-c71","front":"self-fulfilling prophecy","back":"An expectation that causes you to act in ways that make that expectation come true.","sourceNumber":506},{"id":"appsych-unit-4-c72","front":"self-serving bias","back":"A readiness to perceive oneself favorably. 5.","sourceNumber":507},{"id":"appsych-unit-4-c73","front":"social exchange theory","back":"Theory that our social behavior is an exchange process; the aim of which is to maximize benefits and minimize costs.","sourceNumber":528},{"id":"appsych-unit-4-c74","front":"social facilitation","back":"Stronger responses on simple/well-learned tasks in the presence of others.","sourceNumber":529},{"id":"appsych-unit-4-c75","front":"social identity","back":"The \"we\" aspect of our self-concept; the part of our answer to \"Who am I?\" that comes from our group memberships.","sourceNumber":530},{"id":"appsych-unit-4-c76","front":"social loafing","back":"Tendency for people in a group to exert less effort toward attaining a common goal than when by themselves 5.","sourceNumber":532},{"id":"appsych-unit-4-c77","front":"social psychology","back":"The scientific study of how we think about, influence, and relate to one another. 5.","sourceNumber":533},{"id":"appsych-unit-4-c78","front":"social trap","back":"A situation in which the conflicting parties, by each rationally pursuing their self-interest, become caught in mutually destructive behavior.","sourceNumber":535},{"id":"appsych-unit-4-c79","front":"social-cognitive perspective","back":"Views behavior as influenced by the interaction between people's traits (including their thinking) and their social context.","sourceNumber":536},{"id":"appsych-unit-4-c80","front":"social-cultural psychology","back":"The study of how situations and cultures affect our behavior and thinking.","sourceNumber":537},{"id":"appsych-unit-4-c81","front":"social-responsibility norm","back":"An expectation that people will help those dependent upon them.","sourceNumber":538},{"id":"appsych-unit-4-c82","front":"standardization","back":"Defining meaningful scores by comparison with the performance of a pretested group. 5.","sourceNumber":548},{"id":"appsych-unit-4-c83","front":"stereotype","back":"Generalized belief about a group of people.","sourceNumber":551},{"id":"appsych-unit-4-c84","front":"stereotype threat","back":"A self-confirming concern that one will be evaluated based on a negative stereotype. 5.","sourceNumber":552},{"id":"appsych-unit-4-c85","front":"sublimation","back":"Psychoanalytic defense mechanism by which people re-channel their unacceptable impulses into socially approved activities.","sourceNumber":558},{"id":"appsych-unit-4-c86","front":"superego","back":"The part of personality that, according to Freud, represents internalized ideals and provides standards for judgement (the conscience) and for future aspirations.","sourceNumber":560},{"id":"appsych-unit-4-c87","front":"superordinate goals","back":"Shared goals that override differences among people and require their cooperation.","sourceNumber":561},{"id":"appsych-unit-4-c88","front":"terror-management theory","back":"A theory of death-related anxiety; explores people' emotional and behavioral responses to reminders of their impending death.","sourceNumber":572},{"id":"appsych-unit-4-c89","front":"trait","back":"A characteristic pattern of behavior or a disposition to feel and act, as assessed by self-report inventories and peer reports.","sourceNumber":584},{"id":"appsych-unit-4-c90","front":"two-factor theory","back":"The Schachter-Singer theory that to  experience emotion one must (1) be physically aroused and (2) cognitively label the arousal.","sourceNumber":587},{"id":"appsych-unit-4-c91","front":"unconditional positive regard","back":"A caring, accepting, nonjudgmental attitude, which Carl Rogers believed would help clients to develop self-awareness and self-acceptance.","sourceNumber":591},{"id":"appsych-unit-4-c92","front":"unconscious","back":"According to Freud, a reservoir of mostly unacceptable thoughts, wishes, feelings, and memories. According to contemporary psychologists, information processing of which we are unaware.","sourceNumber":595}],"questions":[],"feynmanPrompts":[{"id":"appsych-unit-4-f1","prompt":"Attribution and person perception"},{"id":"appsych-unit-4-f2","prompt":"Attitudes and persuasion"},{"id":"appsych-unit-4-f3","prompt":"Conformity, obedience, and group behavior"},{"id":"appsych-unit-4-f4","prompt":"Prejudice and prosocial behavior"},{"id":"appsych-unit-4-f5","prompt":"Psychoanalytic theories of personality"},{"id":"appsych-unit-4-f6","prompt":"Humanistic and trait theories"},{"id":"appsych-unit-4-f7","prompt":"Social-cognitive theories"},{"id":"appsych-unit-4-f8","prompt":"Motivation"},{"id":"appsych-unit-4-f9","prompt":"Emotion"}]},{"id":"appsych-unit-5","name":"AP Psychology - Unit 5","shortName":"Unit 5: Mental and Physical Health","builtIn":true,"sourceTitle":"Myer's Psychology for AP Vocabulary","sourceUrl":"https://www.bpsgroverteacher.com/uploads/1/4/8/4/14847764/myer_s_psychology_for_ap_vocab.pdf","cedTitle":"AP Psychology Course and Exam Description - Effective Fall 2025","cedUrl":"https://apcentral.collegeboard.org/media/pdf/ap-psychology-course-and-exam-description.pdf","cards":[{"id":"appsych-unit-5-c1","front":"Aaron Beck","back":"Sought to reverse patient's catastrophizing beliefs about themselves, their situations and futures using cognitive therapy.","sourceNumber":1},{"id":"appsych-unit-5-c2","front":"active listening","back":"Empathic listening in which the listener echoes, restates, and clarifies. A feature of Rogers' client centered therapy.","sourceNumber":9},{"id":"appsych-unit-5-c3","front":"addiction","back":"Compulsive drug craving and use, despite adverse consequences.","sourceNumber":11},{"id":"appsych-unit-5-c4","front":"anorexia nervosa","back":"An eating disorder in which a person (usually an adolescent female) diets and becomes significantly (15% or more) underweight, yet, still feeling fat, continues to starve.","sourceNumber":22},{"id":"appsych-unit-5-c5","front":"antianxiety drugs","back":"Drugs used to control anxiety and agitation.","sourceNumber":23},{"id":"appsych-unit-5-c6","front":"antidepressant drugs","back":"Drugs used to treat depression; also increasingly prescribed for anxiety. Different types work by altering the availability of various neurotransmitters.","sourceNumber":24},{"id":"appsych-unit-5-c7","front":"antipsychotic drugs","back":"Drugs used to treat schizophrenia and other forms of severe thought disorder.","sourceNumber":25},{"id":"appsych-unit-5-c8","front":"Antisocial personality disorder","back":"A personality disorder in which the person (usually a man) exhibits a lack of conscience for wrongdoing, even toward friends and family members; may be aggressive and ruthless or a clever con artist.","sourceNumber":26},{"id":"appsych-unit-5-c9","front":"Anxiety disorders","back":"Psychological disorders characterized by distressing, persistent anxiety or maladaptive behaviors that reduce anxiety.","sourceNumber":27},{"id":"appsych-unit-5-c10","front":"Attention-Deficit Hyperactivity Disorder (ADHD)","back":"A psychological disorder marked by the appearance by age  of one or more of three key symptoms: extreme inattention, hyperactivity, and impulsivity.","sourceNumber":35},{"id":"appsych-unit-5-c11","front":"aversive conditioning","back":"A type of counterconditioning that associates an unpleasant states (such as nausea) with an  unwanted behavior (such as drinking).","sourceNumber":43},{"id":"appsych-unit-5-c12","front":"behavior therapy","back":"Therapy that applies learning principles to  the elimination of unwanted behaviors.","sourceNumber":51},{"id":"appsych-unit-5-c13","front":"behavioral medicine","back":"An interdisciplinary field that integrates  behavioral and medical knowledge and applies that knowledge to health and disease.","sourceNumber":52},{"id":"appsych-unit-5-c14","front":"binge-eating disorder","back":"Significant binge-eating episodes,  followed by distress, disgust, or guilt, but without the compensatory purging, fasting, or excessive exercise that marks bulimia nervosa.","sourceNumber":57},{"id":"appsych-unit-5-c15","front":"biofeedback","back":"A system for electronically recording, amplifying, and feeding back information regarding a subtle psychological state, such as blood pressure or muscle tension.","sourceNumber":59},{"id":"appsych-unit-5-c16","front":"biomedical therapy","back":"Prescribed medications or medical procedures that act directly on the patient's nervous system.","sourceNumber":62},{"id":"appsych-unit-5-c17","front":"Bipolar disorder","back":"A mood disorder in which the person alternates between the hopelessness and lethargy of depression and the overexcited state of mania.","sourceNumber":64},{"id":"appsych-unit-5-c18","front":"bulimia nervosa","back":"An eating disorder characterized by episodes of overeating, usually of high-calorie foods, followed by vomiting, laxative use, fasting, or excessive exercise.","sourceNumber":69},{"id":"appsych-unit-5-c19","front":"client centered therapy","back":"A humanistic therapy, developed by Carl Rogers, in which the therapist uses techniques such as active listening within a genuine, accepting, empathic environment to facilitate client's growth. Also called person- centered therapy.","sourceNumber":83},{"id":"appsych-unit-5-c20","front":"clinical psychology","back":"A branch of psychology that studies, assesses, and treats people with psychological disorders.","sourceNumber":84},{"id":"appsych-unit-5-c21","front":"cognitive behavioral therapy","back":"A popular integrative therapy that combines cognitive therapy with behavior therapy.","sourceNumber":89},{"id":"appsych-unit-5-c22","front":"cognitive therapy","back":"Therapy that teaches people new, more adaptive ways of thinking and acting; based on the assumption that thoughts intervene between events and our emotional  reactions.","sourceNumber":95},{"id":"appsych-unit-5-c23","front":"Conversion disorder","back":"A rare somatoform disorder in which a person experiences very specific genuine physical symptoms for which no physiological basis can be found. 1.","sourceNumber":117},{"id":"appsych-unit-5-c24","front":"coronary heart disease","back":"The clogging of the vessels that nourish the heart muscle; the leading cause of death in North  America.","sourceNumber":118},{"id":"appsych-unit-5-c25","front":"counseling psychology","back":"A branch of psychology that assists people with problems in living (often related to school, work, or  marriage) and in achieving greater well-being.","sourceNumber":122},{"id":"appsych-unit-5-c26","front":"counterconditioning","back":"A behavior therapy procedure that uses classical conditioning to evoke new responses to stimuli that are  triggering unwanted behaviors; includes exposure therapies and aversive conditioning.","sourceNumber":123},{"id":"appsych-unit-5-c27","front":"defense mechanisms","back":"In psychoanalytic theory, the ego's protective methods of reducing anxiety by unconsciously distorting reality.","sourceNumber":133},{"id":"appsych-unit-5-c28","front":"Delusions","back":"False beliefs, often of persecution or grandeur, that may accompany psychotic disorders.","sourceNumber":137},{"id":"appsych-unit-5-c29","front":"denial","back":"Psychoanalytic defense mechanism by which people refuse to believe or even to perceive painful realities.","sourceNumber":139},{"id":"appsych-unit-5-c30","front":"Dissociative disorders","back":"Disorders in which conscious awareness becomes separated from previous memories, thoughts, and feelings.","sourceNumber":151},{"id":"appsych-unit-5-c31","front":"Dissociative identity disorder","back":"A rare dissociative disorder in which a person exhibits two or more distinct and alternating personalities. Also called multiple personality disorder.","sourceNumber":152},{"id":"appsych-unit-5-c32","front":"Down syndrome","back":"A condition of intellectual disability and associated physical disorders caused by an extra copy of chromosome 21. 1.","sourceNumber":156},{"id":"appsych-unit-5-c33","front":"DSM-IV-TR","back":"A classification system that describes the features used to diagnose each recognized mental disorder and indicates  how the disorder can be distinguished from other, similar problems.","sourceNumber":159},{"id":"appsych-unit-5-c34","front":"eclectic approach","back":"An approach to psychotherapy that, depending on the client's problems, uses techniques from various forms of therapy.","sourceNumber":162},{"id":"appsych-unit-5-c35","front":"electroconvulsive therapy","back":"A biomedical therapy for severely depressed patients in which a brief electric current is sent through the brain of an aenesthetized patient.","sourceNumber":168},{"id":"appsych-unit-5-c36","front":"exposure therapies","back":"Behavioral techniques, such as systematic desensitization, that treat anxieties by exposing people (in imagination or actualitiy) to the things they fear or avoid.","sourceNumber":189},{"id":"appsych-unit-5-c37","front":"family therapy","back":"Therapy that treats the family as a system.  Views an individual's unwanted behaviors as influenced by or directed at other family members.","sourceNumber":196},{"id":"appsych-unit-5-c38","front":"free association","back":"In psychoanalysis, a method of exploring the unconscious in which the person relaxes and says whatever comes to mind, no matter how trivial or embarrassing.","sourceNumber":214},{"id":"appsych-unit-5-c39","front":"general adaptation syndrome (GAS)","back":"Selye's concept of the body's adaptive response to stress in three phases - alarm, resistance, exhaustion.","sourceNumber":227},{"id":"appsych-unit-5-c40","front":"Generalized Anxiety Disorder","back":"An anxiety disorder in which a person is continually tense, apprehensive, and in a state of autonomic nervous system arousal.","sourceNumber":230},{"id":"appsych-unit-5-c41","front":"hallucinations","back":"False sensory experiences, such as seeing something in the absence of an external visual stimulus 2.","sourceNumber":242},{"id":"appsych-unit-5-c42","front":"health psychology","back":"A subfield of psychology that provides  psychology's contribution to behavioral medicine.","sourceNumber":244},{"id":"appsych-unit-5-c43","front":"Hypochonriasis","back":"A somatoform disorder involving excessive concern about health and disease.","sourceNumber":257},{"id":"appsych-unit-5-c44","front":"learned helplessness","back":"The hopelessness and passive resignation an animal or human learns when unable to avoid repeated aversive events.","sourceNumber":304},{"id":"appsych-unit-5-c45","front":"Major depressive disorder","back":"A mood disorder in which a person experiences, in the absence of drugs or a medical condition, two or more weeks of significantly depressed moods, feelings of worthlessness, and diminished interest or pleasure in most activities. 3.","sourceNumber":317},{"id":"appsych-unit-5-c46","front":"Mania","back":"A mood disorder marked by a hyperactive, wildly optimistic state.","sourceNumber":318},{"id":"appsych-unit-5-c47","front":"Medical Model","back":"The concept that diseases have physical causes that can be diagnosed, treated, and, in most cases, cured,  often through treatment in a hospital.","sourceNumber":323},{"id":"appsych-unit-5-c48","front":"Mood Disorders","back":"Psychological disorders characterized by emotional extremes.","sourceNumber":343},{"id":"appsych-unit-5-c49","front":"Obsessive-compulsive disorder","back":"An anxiety disorder characterized by unwanted repetitive thoughts and/ or actions.","sourceNumber":372},{"id":"appsych-unit-5-c50","front":"Panic disorder","back":"An anxiety disorder marked by unpredictable  minutes-long episodes of intense dread in which a person experiences terror and accompanying chest pain, choking, or other frightening sensations. 4.","sourceNumber":386},{"id":"appsych-unit-5-c51","front":"Personality Disorders","back":"Psychological disorders characterized by inflexible and enduring behavior patterns that impair social functioning.","sourceNumber":403},{"id":"appsych-unit-5-c52","front":"Phobia","back":"An anxiety disorder marked by a persistent, irrational fear and avoidance of a specific object or situation.","sourceNumber":408},{"id":"appsych-unit-5-c53","front":"positive psychology","back":"The scientific study of optimal human functioning; aims to discover and promote strengths and virtues that enable individuals and communities to thrive. 4.","sourceNumber":418},{"id":"appsych-unit-5-c54","front":"Post-Traumatic Stress Disorder","back":"An anxiety disorder characterized by haunting memories, nightmares, social withdrawal, jumpy anxiety, and/or insomnia that lingers for four weeks or more after a traumatic experience.","sourceNumber":421},{"id":"appsych-unit-5-c55","front":"psychiatry","back":"A branch of medicine dealing with psychological disorders; practiced by physicians who sometimes provide medical (for example, drug) treatments as well as psychological therapy.","sourceNumber":435},{"id":"appsych-unit-5-c56","front":"psychoanalysis","back":"Sigmond Freud's therapeutic technique. Freud believed the patient's free associations, resistances, dreams, and transferences and the therapists interpretations of them released previously repressed feelings, allowing the patient to gain self-insight.","sourceNumber":438},{"id":"appsych-unit-5-c57","front":"psychodynamic psychology","back":"A branch of psychology that studies how unconscious drives and conflicts influence behavior, and uses that information to treat people with psychological disorders.","sourceNumber":439},{"id":"appsych-unit-5-c58","front":"psychodynamic therapy","back":"Therapy deriving from the psychoanalytic tradition that views individuals as responding to unconscious forces and childhood experiences, and that seeks to enhance self-insight.","sourceNumber":440},{"id":"appsych-unit-5-c59","front":"Psychological Disorder","back":"Deviant, distressful, and dysfunctional patterns of thoughts, feelings, or behaviors.","sourceNumber":442},{"id":"appsych-unit-5-c60","front":"psychopharmacology","back":"The study of the effects of drugs on mind and behavior.","sourceNumber":446},{"id":"appsych-unit-5-c61","front":"psychophysiological illness","back":"Literally, \"mind-body\" illness; any stress-related physical illness, such as hypertension and some headaches.","sourceNumber":448},{"id":"appsych-unit-5-c62","front":"psychotherapy","back":"Treatment involving psychological techniques; consists of interactions between a trained therapist and someone seeking to overcome psychological difficulties or achieve personal growth 4.","sourceNumber":451},{"id":"appsych-unit-5-c63","front":"rationalization","back":"Psychoanalytic defense mechanism that offers self-justifying explanations in place of the real, more threatening, unconscious reasons for one's actions.","sourceNumber":458},{"id":"appsych-unit-5-c64","front":"reaction formation","back":"Psychoanalytic defense mechanism by  which the ego unconsciously switches unacceptable impulses into their opposites, Thus, people may express feelings that are opposite of their anxiety-arousing unconscious feelings. 4.","sourceNumber":459},{"id":"appsych-unit-5-c65","front":"repetitive transcranial magnetic stimulation","back":"The application of repeated pulses of magnetic energy to the brain; used to stimulate or suppress brain activity.","sourceNumber":475},{"id":"appsych-unit-5-c66","front":"repression","back":"The psychoanalytic theory, the basis defense mechanism that banishes from consciousness anxiety-arousing thoughts, feelings, and memories.","sourceNumber":479},{"id":"appsych-unit-5-c67","front":"resilience","back":"The personal strength that helps most people cope with stress and recover from adversity and even trauma.","sourceNumber":480},{"id":"appsych-unit-5-c68","front":"resistance","back":"In psychoanalysis, the blocking from consciousness of anxiety laden material.","sourceNumber":481},{"id":"appsych-unit-5-c69","front":"Schizophrenia","back":"A group of severe disorders characterized by disorganized and delusional thinking, disturbed perceptions,  and inappropriate emotions and actions.","sourceNumber":497},{"id":"appsych-unit-5-c70","front":"Somatic symptom disorder","back":"Psychological disorder in which the symptoms take a bodily form without apparent physical cause.","sourceNumber":540},{"id":"appsych-unit-5-c71","front":"stress","back":"The process by which we perceive and respond to certain events, called stressors, that we appraise as threatening or challenging.","sourceNumber":556},{"id":"appsych-unit-5-c72","front":"systematic desensitization","back":"A type of exposure therapy that associates a pleasant relaxed state with gradually increasing anxiety-triggering stimuli. Commonly used to treat phobias.","sourceNumber":566},{"id":"appsych-unit-5-c73","front":"tardive dyskinesia","back":"Involuntary movements of the facial muscles, tongue, and limbs; a possible neurotoxic side effect of long-term use of antipsychotic drugs that target certain dopamine receptors.","sourceNumber":567},{"id":"appsych-unit-5-c74","front":"token economy","back":"An operant conditioning procedure in which  people earn a token of some sort or exhibiting a desired behavior and can later exchange the tokens for various privileges or treats.","sourceNumber":581},{"id":"appsych-unit-5-c75","front":"transference","back":"In psychoanalysis, the patient's transfer to the analyst of emotions linked with other relationships (such as love or hatred for a parent).","sourceNumber":586},{"id":"appsych-unit-5-c76","front":"Type A","back":"Friedman and Rosenman's term for competitive, hard- driving, impatient, verbally aggressive, and anger-prone people.","sourceNumber":589},{"id":"appsych-unit-5-c77","front":"virtual reality exposure therapy","back":"An anxiety treatment that progressively exposes people to simulations of their greatest fears such as airplane flying, spiders, or public speaking.","sourceNumber":600},{"id":"appsych-unit-5-c78","front":"well-being","back":"Self-perceived happiness or satisfaction with life; used along measures of objective well-being (for example, physical and economic indicators) to evaluate people's quality of life.","sourceNumber":606}],"questions":[],"feynmanPrompts":[{"id":"appsych-unit-5-f1","prompt":"Stress and health"},{"id":"appsych-unit-5-f2","prompt":"Positive psychology and well-being"},{"id":"appsych-unit-5-f3","prompt":"Classifying psychological disorders"},{"id":"appsych-unit-5-f4","prompt":"Anxiety and trauma-related disorders"},{"id":"appsych-unit-5-f5","prompt":"Mood and psychotic disorders"},{"id":"appsych-unit-5-f6","prompt":"Personality and neurodevelopmental disorders"},{"id":"appsych-unit-5-f7","prompt":"Psychotherapy"},{"id":"appsych-unit-5-f8","prompt":"Biomedical treatments"}]}];
